// 历史人物（上古至公元前后）。行迹年份多为约数；地点坐标取遗址或今城市位置。
import type { Figure } from '../../types.ts';
import { w } from './waypoint.ts';

export const FIGURES_ANTIQUITY: Figure[] = [
  {
    id: 'buddha',
    name: { zh: '释迦牟尼', en: 'Gautama Buddha' },
    birth: -563, death: -483, approx: true,
    title: { zh: '佛教创始人', en: 'Founder of Buddhism' },
    region: 'south-asia', lineage: 'india', sprite: 'walker',
    summary: {
      zh: '古印度释迦族王子，本名乔达摩·悉达多，佛教创始人。相传二十九岁出家，苦修六年后在菩提伽耶悟道，此后四十余年在恒河中游各地游化说法，提出四谛、八正道、缘起等教义，八十岁时在拘尸那罗入灭。其生卒年另有约前480—前400年等说法，此处取传统说法；各站的年份出自后世佛传，均为约数。',
      en: 'A prince of the Shakya clan in ancient India, born Siddhartha Gautama, and the founder of Buddhism. According to tradition he left home at twenty-nine, practised austerities for six years and attained enlightenment at Bodh Gaya. For more than forty years he then walked the middle Ganges plain teaching the Four Noble Truths, the Eightfold Path and dependent origination, and died at Kushinagar aged eighty. His dates are disputed (many scholars prefer c. 480-400 BCE); the traditional chronology is used here, and the years of individual stops, drawn from later biographies, are approximate.',
    },
    route: [
      w(-563, 83.276, 27.469,
        ['蓝毗尼（今尼泊尔南部）', '生于释迦族', '相传摩耶夫人回娘家待产，途经蓝毗尼园时在树下生下太子悉达多。公元前3世纪阿育王到此朝拜并立石柱，柱上的铭文是确认佛陀诞生地的重要依据。'],
        ['Lumbini (southern Nepal)', 'Born into the Shakya clan', "According to tradition Queen Maya gave birth to Prince Siddhartha beneath a tree in the Lumbini grove while travelling to her parents' home. The pillar that Emperor Ashoka set up here in the 3rd century BCE is key evidence for identifying the birthplace."],
        { wiki: { zh: '蓝毗尼', en: 'Lumbini' } }),
      w(-534, 83.05, 27.57,
        ['迦毗罗卫（释迦族都城，一般认为在今尼泊尔提劳拉科特）', '二十九岁出家修行', '悉达多在迦毗罗卫的宫廷中长大，娶妻耶输陀罗，生子罗睺罗。佛传说他出城时先后见到老人、病人、死者和修行者，深感人生无常，在二十九岁的一个夜晚离家，剃发成为游方的沙门。'],
        ['Kapilavastu (Shakya capital, probably Tilaurakot, Nepal)', 'Leaves home at twenty-nine', "Siddhartha grew up at the Shakya court, married Yashodhara and had a son, Rahula. The traditional accounts say that the sight of an old man, a sick man, a corpse and a wandering ascetic convinced him of life's impermanence, and one night he left the palace to become a mendicant."]),
      w(-533, 85.42, 25.03,
        ['王舍城（摩揭陀国都城，今印度比哈尔邦拉杰吉尔）', '南下摩揭陀，寻师问道', '悉达多渡过恒河来到摩揭陀国都王舍城，相传国王频婆娑罗曾劝他留下，被他谢绝。此后他先后跟随阿罗逻·迦罗摩和郁陀迦·罗摩子两位禅师学习禅定，很快达到老师的境界，却认为这仍不是解脱之道。'],
        ['Rajagriha (capital of Magadha, now Rajgir, Bihar)', 'Goes south to Magadha in search of a teacher', 'Siddhartha crossed the Ganges to Rajagriha, where King Bimbisara is said to have offered him a place at court. He went on to study meditation under two teachers, Alara Kalama and Uddaka Ramaputta, quickly matched their attainments, and concluded that these did not lead to liberation.']),
      w(-532, 85.07, 24.77,
        ['优楼频螺（尼连禅河畔，今菩提伽耶附近）', '苦行六年', '他与憍陈如等五位同伴在尼连禅河一带的山林中修极端的苦行，相传每日只吃极少的食物，瘦得皮骨相连。六年后他认识到折磨身体无益于觉悟，接受了牧女善生供养的乳糜，五位同伴以为他半途而废，离他而去。'],
        ['Uruvela (by the Nairanjana river, near Bodh Gaya)', 'Six years of austerities', 'With five companions he practised extreme austerities in the hills and woods near the Nairanjana river, by tradition eating so little that he was reduced to skin and bone. After six years he judged self-mortification useless and accepted a bowl of milk-rice from the village girl Sujata; his companions left him in disgust.']),
      w(-528, 84.991, 24.696,
        ['菩提伽耶（今印度比哈尔邦）', '于菩提树下悟道成佛', '三十五岁的悉达多在一棵毕钵罗树（后称菩提树）下静坐，发誓不成正觉不起此座，相传在黎明时分彻悟，自此被称为“佛陀”（觉者）。今天的摩诃菩提寺和菩提树就在这一地点，是佛教最重要的圣地。'],
        ['Bodh Gaya (Bihar, India)', 'Attains enlightenment beneath the Bodhi tree', 'Aged thirty-five, Siddhartha sat beneath a pipal tree, later called the Bodhi tree, vowing not to rise until he had found the truth, and by tradition awoke at dawn. From then on he was the Buddha, the "awakened one". The Mahabodhi Temple and a descendant of the tree mark the spot today.'],
        { event: 'buddha-enlightenment', wiki: { zh: '摩诃菩提寺', en: 'Mahabodhi Temple' } }),
      w(-528, 83.025, 25.381,
        ['鹿野苑（今印度瓦拉纳西附近的萨尔纳特）', '初转法轮，度五比丘', '佛陀步行两百多公里来到波罗奈城外的鹿野苑，找到离他而去的五位同伴，为他们讲说中道、四圣谛和八正道，史称“初转法轮”。五人皈依成为最早的比丘，佛、法、僧“三宝”至此具足。'],
        ['Sarnath (the Deer Park, near Varanasi, India)', 'Preaches his first sermon to five disciples', 'The Buddha walked more than 200 km to the Deer Park outside Varanasi, found his five former companions and taught them the Middle Way, the Four Noble Truths and the Eightfold Path, a sermon known as the first turning of the wheel of Dharma. They became the first monks, and the Buddhist community was born.'],
        { wiki: { zh: '鹿野苑', en: 'Sarnath' } }),
      w(-520, 85.42, 25.03,
        ['王舍城', '受摩揭陀国王供养，弘法于竹林精舍', '佛陀带着弟子回到王舍城，频婆娑罗王皈依并献出城外的竹林，建成佛教最早的寺院竹林精舍。舍利弗与目犍连在此率众来归，成为他的两大弟子；城外的灵鹫山也是他经常说法的地方。'],
        ['Rajagriha', 'Teaches at the Bamboo Grove under royal patronage', 'Returning to Rajagriha with his followers, the Buddha won over King Bimbisara, who gave him the Bamboo Grove outside the city, the first Buddhist monastery. Here Shariputra and Maudgalyayana joined him and became his two chief disciples; he also taught often on nearby Vulture Peak.'],
        { wiki: { zh: '王舍城', en: 'Rajgir' } }),
      w(-519, 83.05, 27.57,
        ['迦毗罗卫', '重返故乡，族人纷纷出家', '相传佛陀应父亲净饭王之请，从王舍城回到迦毗罗卫，在故城街头托钵乞食。他的儿子罗睺罗、异母弟难陀随他出家，阿难、阿那律等释迦族子弟和理发匠出身的优波离也在这次返乡之后加入僧团。'],
        ['Kapilavastu', 'Returns home; many Shakyas join the order', 'At the request of his father King Suddhodana, tradition says, the Buddha travelled from Rajagriha back to Kapilavastu and begged for alms in the streets of his own city. His son Rahula and half-brother Nanda were ordained, and Shakya nobles such as Ananda and Anuruddha, with the barber Upali, joined soon after the visit.']),
      w(-517, 85.13, 25.99,
        ['毗舍离（离车族都城，今印度比哈尔邦）', '允许女性出家，比丘尼僧团成立', '相传佛陀的姨母兼养母摩诃波阇波提率领一批释迦族妇女，剃发赤足走到毗舍离请求出家。佛陀起初不许，经阿难再三代为恳请才答应，佛教由此有了比丘尼僧团。'],
        ['Vaishali (capital of the Licchavis, Bihar, India)', 'Admits women: the order of nuns begins', 'Tradition holds that Mahaprajapati, the aunt who had raised him, walked to Vaishali with a group of Shakya women, heads shaved and feet bare, to ask for ordination. The Buddha at first refused and relented only after Ananda pleaded on their behalf, so founding the order of nuns.']),
      w(-515, 81.39, 25.34,
        ['憍赏弥（跋蹉国都城，今印度北方邦）', '在憍赏弥说法，调解僧团争执', '憍赏弥是亚穆纳河畔的商业大城，富商瞿师罗在此献出园林供僧团居住。经典记载这里的比丘曾因戒律细节争执不休，佛陀劝解无效，独自离开到林中静住，僧众这才和解。'],
        ['Kaushambi (capital of Vatsa, Uttar Pradesh, India)', 'Teaches at Kaushambi and faces a quarrel among monks', 'Kaushambi was a trading city on the Yamuna, where the merchant Ghosita gave a park to the order. The scriptures record that the monks here fell into a bitter dispute over a point of discipline; unable to reconcile them, the Buddha withdrew alone to the forest until they made peace.']),
      w(-500, 82.04, 27.51,
        ['舍卫城（拘萨罗国都城，今印度北方邦）', '于祇园精舍长期说法', '富商给孤独长者相传以黄金铺地，向祇陀太子买下园林献给佛陀，是为祇园精舍。佛陀后半生有二十多个雨季在舍卫城度过，许多经典以“一时佛在舍卫国祇树给孤独园”开篇。'],
        ['Shravasti (capital of Kosala, Uttar Pradesh, India)', 'Teaches for many years at Jetavana', "The merchant Anathapindika is said to have covered the ground with gold coins to buy Prince Jeta's grove for the Buddha, founding the Jetavana monastery. The Buddha spent more than twenty rainy seasons at Shravasti, and a large share of his recorded discourses were delivered here."],
        { wiki: { zh: '祇园精舍', en: 'Jetavana' } }),
      w(-484, 85.14, 25.61,
        ['巴连弗邑（后来的华氏城，今印度巴特那）', '最后的旅程：渡恒河北上', '年近八十的佛陀从王舍城灵鹫山动身北行。据《大般涅槃经》，他在恒河岸边的巴连弗邑看到摩揭陀大臣正在筑城，预言此地将成为繁华的大都会；这里后来果然成为孔雀王朝的都城华氏城。'],
        ['Pataligrama (later Pataliputra, now Patna, India)', 'The last journey: north across the Ganges', 'Nearly eighty, the Buddha set out north from Vulture Peak at Rajagriha. According to the Mahaparinibbana Sutta he saw Magadhan ministers fortifying the riverside village of Pataligrama and foretold that it would become a great city; it later became Pataliputra, capital of the Mauryan empire.']),
      w(-484, 85.13, 25.99,
        ['毗舍离', '最后一个雨季，预告三月后入灭', '佛陀在毗舍离接受了名妓庵摩罗女供养的芒果园，随后在城外的村庄度过最后一个雨季，其间重病一场。他告诉阿难，自己所说之法并无保留，弟子应当“以自己为洲、以法为洲”；离城时预告三个月后将入涅槃。'],
        ['Vaishali', 'Last rainy season; foretells his death', 'At Vaishali the Buddha accepted a mango grove from the courtesan Amrapali and spent his last rainy season in a nearby village, where he fell gravely ill. He told Ananda that he had held nothing back and that the monks should be "islands unto themselves", then announced that he would pass away in three months.']),
      w(-483, 84.05, 26.68,
        ['波婆城（一般认为在今印度北方邦法齐尔讷格尔一带）', '受铁匠纯陀最后的供养', '佛陀一行来到末罗族的波婆城，住在铁匠之子纯陀的芒果林中，吃了他供养的一餐饭后腹痛剧烈、病势转重。佛陀特意嘱咐阿难转告纯陀不必自责，说这最后一餐的供养功德极大，然后强撑着继续前行。'],
        ['Pava (probably near Fazilnagar, Uttar Pradesh, India)', 'Receives his last meal from Cunda the smith', 'In the Malla town of Pava the Buddha stayed in the mango grove of Cunda, a smith, and fell violently ill after the meal Cunda offered. He asked Ananda to assure Cunda that he bore no blame and that the gift of a last meal earned great merit, then pressed on.']),
      w(-483, 83.888, 26.741,
        ['拘尸那罗（今印度北方邦）', '入涅槃，年八十', '佛陀在拘尸那罗城外的娑罗双树间右胁而卧，对弟子留下最后的教诫：“诸行无常，当精进不放逸。”随后入灭。遗体火化后，舍利由摩揭陀、释迦、末罗等八方分去建塔供养。'],
        ['Kushinagar (Uttar Pradesh, India)', 'Enters parinirvana at the age of eighty', 'The Buddha lay down on his right side between two sal trees outside Kushinagar and gave his last instruction: "All conditioned things are subject to decay; strive on with diligence." After the cremation his relics were divided among eight claimants, who built stupas over them.'],
        { wiki: { zh: '拘尸那揭罗', en: 'Kushinagar' } }),
    ],
    wiki: { zh: '释迦牟尼', en: 'The Buddha' },
  },
  {
    id: 'confucius',
    name: { zh: '孔子', en: 'Confucius' },
    birth: -551, death: -479,
    title: { zh: '思想家、教育家', en: 'Philosopher and teacher' },
    region: 'china', lineage: 'china', sprite: 'walker',
    summary: {
      zh: '春秋末期鲁国人，名丘，字仲尼，儒家学派创始人。早年设教授徒，曾任鲁国大司寇，后率弟子周游列国十四年，宣扬以“仁”“礼”为核心的政治主张而未获重用。晚年返鲁整理典籍、专心教学，相传弟子三千。其言行由弟子及再传弟子辑为《论语》，对中国乃至东亚文明影响深远。',
      en: 'A native of the state of Lu in the late Spring and Autumn period, personal name Qiu, courtesy name Zhongni, and the founder of the Confucian school. He began teaching as a young man and rose to be minister of justice in Lu, then spent fourteen years travelling among the states with his disciples, urging rulers to govern through benevolence (ren) and ritual propriety (li), without finding one who would employ him. In old age he returned to Lu to teach and edit the classics; tradition credits him with three thousand students. His sayings, compiled as the Analects, shaped the civilisation of China and East Asia.',
    },
    route: [
      w(-551, 116.99, 35.58,
        ['陬邑（今山东曲阜东南）', '生于鲁国陬邑', '孔子的父亲叔梁纥是陬邑大夫，以勇力闻名，母亲颜徵在。相传父母曾到尼丘山祈祷而得子，故名丘、字仲尼。孔子三岁丧父，随母亲迁居鲁都曲阜，在贫寒中长大。'],
        ['Zou (southeast of present Qufu, Shandong)', 'Born in the town of Zou in Lu', "Confucius's father Shuliang He was a minor official of Zou known for his strength; his mother was Yan Zhengzai. Tradition says they prayed for a son at Mount Ni, hence his names Qiu and Zhongni. His father died when he was three, and he grew up poor in the Lu capital, Qufu."],
        { wiki: { zh: '尼山', en: 'Mount Ni' } }),
      w(-522, 116.99, 35.58,
        ['曲阜（鲁国都城）', '三十而立，开始收徒讲学', '孔子年轻时做过管理仓库和牧场的小吏，自称“十有五而志于学”，到三十岁前后已以通晓礼乐知名，开始招收弟子。他主张“有教无类”，只要送上一束干肉作见面礼就肯教，打破了贵族对教育的垄断。'],
        ['Qufu (capital of Lu)', 'Begins to take students around the age of thirty', 'As a young man Confucius kept accounts for granaries and herds while teaching himself the rites and music. By about thirty he was known for his learning and began to accept students, whatever their birth, in return for a token gift of dried meat, opening education beyond the hereditary nobility.']),
      w(-518, 112.43, 34.67,
        ['洛邑（东周王城，今河南洛阳）', '相传适周问礼于老子', '据《史记》记载，孔子在鲁国贵族南宫敬叔陪同下前往周王室所在的洛邑，考察礼乐制度和典籍，并向掌管藏书的老子请教。此事的年代和真实性历来有争议，汉代画像石中常见“孔子见老子”的题材。'],
        ['Luoyi (Eastern Zhou royal capital, now Luoyang, Henan)', 'Said to have consulted Laozi on ritual', 'According to the Records of the Grand Historian, Confucius travelled to the Zhou royal capital to study its rites, music and archives, and questioned Laozi, keeper of the royal library. The date and historicity of the meeting are disputed, but it became a favourite subject of Han-dynasty stone reliefs.'],
        { wiki: { zh: '老子', en: 'Laozi' } }),
      w(-517, 118.35, 36.87,
        ['临淄（齐国都城，今山东淄博）', '鲁国内乱，适齐', '鲁昭公讨伐季孙氏失败，逃亡齐国，孔子不久也到了齐国。齐景公向他问政，他答以“君君、臣臣、父父、子子”；他在齐国听到《韶》乐，赞叹“三月不知肉味”。景公一度想任用他，终未成事，他一两年后返回鲁国。'],
        ['Linzi (capital of Qi, now Zibo, Shandong)', 'Goes to Qi during the turmoil in Lu', "After Duke Zhao of Lu failed to crush the Jisun clan and fled to Qi, Confucius followed. He told Duke Jing that good government means ruler, minister, father and son each keeping to his role, and the Shao music so moved him that for three months he 'did not notice the taste of meat'. Given no post, he went home."]),
      w(-501, 116.99, 35.58,
        ['曲阜', '出任中都宰，后升任大司寇', '阳虎之乱平定后，五十一岁的孔子受鲁定公任命为中都（今山东汶上）宰，据说一年间政绩卓著，四方仿效。此后他升任司空，又任掌管刑狱的大司寇，开始参与鲁国国政。'],
        ['Qufu', 'Appointed magistrate of Zhongdu, then minister of justice', 'Once the usurper Yang Hu had been driven out, Duke Ding of Lu made the fifty-one-year-old Confucius magistrate of Zhongdu (now Wenshang, Shandong), where his administration was reportedly taken as a model. He was promoted to minister of works and then minister of justice, with a voice in the affairs of Lu.']),
      w(-500, 117.68, 36.15,
        ['夹谷（一说在今山东莱芜）', '夹谷之会，以礼折服齐国', '鲁定公与齐景公在夹谷会盟，孔子担任相礼。据《左传》，齐人想让莱夷武士劫持鲁君，孔子挺身指挥护卫并据礼斥责，齐景公只得作罢，事后归还了侵占鲁国的郓、讙、龟阴之田。夹谷的位置有不同说法。'],
        ['Jiagu (possibly near Laiwu, Shandong)', 'Faces down Qi at the Jiagu meeting', 'Confucius was master of ceremonies when Duke Ding of Lu met Duke Jing of Qi at Jiagu. According to the Zuo Commentary, Qi tried to have Lai tribesmen seize the duke; Confucius called up the guards and rebuked Qi for breaching ritual, and Qi later returned lands it had taken from Lu. The site is disputed.']),
      w(-497, 115.03, 35.76,
        ['帝丘（卫国都城，今河南濮阳）', '离鲁适卫，开始周游列国', '孔子主张拆毁季孙、叔孙、孟孙三家私邑的城墙以强公室，“堕三都”半途而废；鲁国君臣又沉迷于齐国所赠的女乐，他失望之下带着弟子离开鲁国，先到卫国。此后十四年间，他辗转卫、宋、陈、蔡等国，始终未获重用。'],
        ['Diqiu (capital of Wey, now Puyang, Henan)', 'Leaves Lu and begins his wanderings', "His plan to pull down the walls of the three great clans' strongholds had stalled, and the court was distracted by a gift of dancing girls from Qi. Disillusioned, Confucius left Lu with his disciples and went first to Wey. For the next fourteen years he travelled among the states seeking a ruler who would put his teachings into practice."],
        { event: 'confucius-travels', wiki: { zh: '濮阳市', en: 'Puyang' } }),
      w(-496, 114.67, 35.2,
        ['匡（今河南长垣）', '被匡人围困五日', '孔子离开卫都南行，路过匡邑。匡人曾受阳虎欺凌，而孔子相貌与阳虎相似，于是被团团围住五天。弟子们十分恐惧，孔子却说：“天之未丧斯文也，匡人其如予何！”脱险后他折回卫国。'],
        ['Kuang (now Changyuan, Henan)', 'Besieged for five days at Kuang', 'Travelling south from the Wey capital, Confucius was mistaken at Kuang for Yang Hu, who had once mistreated the townspeople, and was surrounded for five days. He calmed his frightened disciples by saying that if Heaven did not mean this culture to perish, the men of Kuang could do nothing to him. He then turned back to Wey.']),
      w(-492, 115.65, 34.41,
        ['宋（都城在今河南商丘）', '过宋，司马桓魋欲加害', '孔子离开卫国，经曹国到宋国，与弟子在大树下演习礼仪。宋国司马桓魋想杀他，派人把树砍倒。弟子催他快走，孔子说“天生德于予，桓魋其如予何”，随后换上便服悄悄离开宋境。'],
        ['Song (capital at present Shangqiu, Henan)', 'Threatened by Huan Tui in Song', "Passing through Cao into Song, Confucius was practising the rites with his disciples under a great tree when Huan Tui, Song's minister of war, who wanted him dead, had the tree cut down. 'Heaven produced the virtue that is in me; what can Huan Tui do to me?' he said, and left Song in disguise."]),
      w(-492, 113.74, 34.4,
        ['郑（都城在今河南新郑）', '与弟子失散，被人喻为“丧家之狗”', '孔子在郑国都城与弟子走散，独自站在东门外。有郑人向子贡形容他额头像尧、脖子像皋陶，却“累累若丧家之狗”。子贡如实转告，孔子欣然笑道：长相未必如此，说像丧家之狗，“然哉！然哉！”'],
        ['Zheng (capital at present Xinzheng, Henan)', 'Lost at the city gate, "like a stray dog"', 'Separated from his disciples in the Zheng capital, Confucius waited alone outside the east gate. A local described him to Zigong as a man with the brow of a sage-king who looked "as forlorn as a stray dog". Told of this, Confucius laughed and agreed that the last part was true enough.']),
      w(-491, 114.88, 33.73,
        ['陈（都城宛丘，今河南淮阳）', '居陈三年', '孔子到陈国后住在司城贞子家中，前后约三年。其间吴国与楚国轮番攻伐陈国，局势动荡。他思念故乡的弟子，感叹道：“归与！归与！吾党之小子狂简，斐然成章，不知所以裁之。”'],
        ['Chen (capital Wanqiu, now Huaiyang, Henan)', 'Stays three years in Chen', 'Confucius lodged in Chen for about three years while the small state was fought over by Wu and Chu. Thinking of the young followers he had left in Lu, he sighed: "Let me go home! My young men there are ambitious and accomplished, but do not yet know how to shape themselves."']),
      w(-489, 114.6, 33.1,
        ['陈、蔡之间', '绝粮七日，弦歌不衰', '楚昭王派人聘请孔子，他在前往楚国的途中被困于陈、蔡之间的荒野，粮食断绝，随行弟子多饿病不起。孔子照旧讲诵弦歌，对愠怒的子路说：“君子固穷，小人穷斯滥矣。”'],
        ['Between Chen and Cai', 'Seven days without food between Chen and Cai', 'On his way to answer an invitation from King Zhao of Chu, Confucius was stranded in open country between Chen and Cai. Supplies ran out and his followers fell ill with hunger, but he went on teaching and playing the zither. "The gentleman stays firm in hardship," he told an angry Zilu; "the petty man loses all restraint."']),
      w(-489, 114.07, 32.13,
        ['负函（楚地，今河南信阳）', '见楚国叶公', '孔子进入楚国北境，在负函见到镇守当地的叶公沈诸梁。叶公问政，孔子答：“近者说，远者来。”据《史记》，楚昭王本想封给孔子土地，被令尹子西劝止，不久昭王病逝军中，孔子南游至此而止。'],
        ['Fuhan (Chu territory, now Xinyang, Henan)', 'Meets the Duke of She in Chu', "At Fuhan on Chu's northern frontier Confucius met its governor Shen Zhuliang, Duke of She, and told him that good government makes 'those near happy and those far away come'. King Zhao of Chu is said to have thought of granting Confucius land but was dissuaded, and soon died on campaign. This was the southernmost point of his travels."]),
      w(-488, 115.03, 35.76,
        ['帝丘（今河南濮阳）', '返回卫国', '孔子从楚地北返，再次回到卫国。此时卫出公与流亡在外的父亲蒯聩争位，子路问为政以何为先，孔子答“必也正名乎”。他的几位弟子在卫国做官，他本人受到礼遇却不参与政事，在卫又住了约五年。'],
        ['Diqiu (now Puyang, Henan)', 'Returns to Wey', "Confucius came back north to Wey, where Duke Chu was contesting the throne with his own exiled father. Asked by Zilu what he would do first in government, he answered: 'Rectify names.' Several disciples held office in Wey; Confucius himself was treated with respect but took no part in affairs, and stayed about five more years."]),
      w(-484, 116.99, 35.58,
        ['曲阜', '返鲁，整理《诗》《书》，修《春秋》', '弟子冉求为季氏率军击退齐军，季康子遂以厚礼迎孔子回国，这时他已六十八岁。鲁国尊他为“国老”却终不能用，他便专心教学，相传整理了《诗》《书》和礼乐，并据鲁国史记修订《春秋》。'],
        ['Qufu', 'Returns to Lu to teach and edit the classics', 'After his disciple Ran Qiu won a victory over Qi for the Jisun clan, Ji Kangzi invited Confucius home with honours; he was sixty-eight. Respected as an elder statesman but given no office, he devoted himself to teaching and, by tradition, to editing the Odes, the Documents and the Spring and Autumn Annals of Lu.'],
        { wiki: { zh: '曲阜孔庙', en: 'Temple of Confucius, Qufu' } }),
      w(-479, 116.99, 35.58,
        ['曲阜', '卒，葬于鲁城北泗水之上（今孔林）', '独子孔鲤和最得意的弟子颜回、子路先后去世，孔子深受打击。前479年夏历四月他病逝，享年七十三岁（虚岁），葬在鲁城以北的泗水边。弟子们为他守丧三年，子贡更在墓旁结庐六年；墓地后来扩展为孔林。'],
        ['Qufu', 'Dies and is buried north of the city', 'Confucius outlived his only son Kong Li and his favourite disciples Yan Hui and Zilu. He died in 479 BCE, aged seventy-three by Chinese reckoning, and was buried by the Si river north of Qufu. His disciples mourned for three years, Zigong for six beside the grave, around which the Cemetery of Confucius later grew.'],
        { wiki: { zh: '孔林', en: 'Cemetery of Confucius' } }),
    ],
    wiki: { zh: '孔子', en: 'Confucius' },
  },
  {
    id: 'aristotle',
    name: { zh: '亚里士多德', en: 'Aristotle' },
    birth: -384, death: -322,
    title: { zh: '哲学家、科学家', en: 'Philosopher and scientist' },
    region: 'europe', sprite: 'scroll',
    summary: {
      zh: '古希腊哲学家，柏拉图的学生、亚历山大大帝的老师。生于爱琴海北岸的斯塔基拉，十七岁入雅典柏拉图学园，后游学小亚细亚和莱斯沃斯岛，并在马其顿宫廷任教。前335年回到雅典创办吕克昂学园，著述涵盖逻辑学、形而上学、伦理学、政治学、诗学、生物学和物理学，被称为“百科全书式的学者”，其思想对欧洲与伊斯兰世界的学术影响长达两千年。',
      en: "Greek philosopher, pupil of Plato and tutor of Alexander the Great. Born at Stagira on the north Aegean coast, he entered Plato's Academy in Athens at seventeen, later worked in Asia Minor and on Lesbos, and taught at the Macedonian court. In 335 BCE he returned to Athens and founded the Lyceum. His writings span logic, metaphysics, ethics, politics, poetics, biology and physics, and shaped scholarship in Europe and the Islamic world for some two thousand years.",
    },
    route: [
      w(-384, 23.79, 40.53,
        ['斯塔基拉（今希腊哈尔基季基半岛东岸）', '生于爱琴海北岸的斯塔基拉', '斯塔基拉是安德罗斯岛移民在哈尔基季基半岛建立的希腊小城。父亲尼各马可是马其顿国王阿敏塔斯三世的御医，这层关系后来把亚里士多德带回了马其顿宫廷。他幼年父母双亡，由监护人普罗克塞诺斯抚养长大。'],
        ['Stagira (east coast of Chalcidice, Greece)', 'Born at Stagira on the north Aegean coast', "Stagira was a small Greek city in Chalcidice founded by colonists from Andros. Aristotle's father Nicomachus was physician to King Amyntas III of Macedon, a connection that later drew his son back to the Macedonian court. Orphaned young, Aristotle was brought up by a guardian, Proxenus."]),
      w(-367, 23.7275, 37.9838,
        ['雅典', '入柏拉图学园求学近二十年', '十七岁的亚里士多德来到雅典，进入柏拉图在城外创办的学园，从学生成为研究者和讲师，一待近二十年。相传柏拉图称他为“学园之灵”；他敬重老师，却逐渐对理念论提出批评，后人用“吾爱吾师，吾更爱真理”概括他的态度。'],
        ['Athens', "Studies at Plato's Academy for nearly twenty years", "At seventeen Aristotle came to Athens and joined the Academy that Plato had founded outside the city walls, staying almost twenty years as student, researcher and lecturer. Plato is said to have called him 'the mind of the school'. He honoured his teacher but came to criticise the theory of Forms."],
        { sea: true, via: [[24.2, 40.52], [24.55, 40.1], [24.95, 39.2], [24.85, 38.45], [24.66, 38.05], [24.6, 37.93], [24.22, 37.8], [24.03, 37.55], [23.78, 37.72]], wiki: { zh: '柏拉图学院', en: 'Platonic Academy' } }),
      w(-347, 26.34, 39.49,
        ['阿索斯（小亚细亚西北海岸，今土耳其贝赫拉姆卡莱）', '柏拉图去世后离开雅典', '柏拉图去世，学园由其外甥斯彪西波接掌，雅典的反马其顿情绪也日益高涨。亚里士多德应同学、阿塔纽斯统治者赫米亚斯之邀渡海来到阿索斯，在此讲学约三年，并娶赫米亚斯的侄女（一说养女）皮西亚斯为妻。'],
        ['Assos (northwest coast of Asia Minor, now Behramkale, Turkey)', "Leaves Athens after Plato's death", "When Plato died the Academy passed to his nephew Speusippus, and anti-Macedonian feeling in Athens was running high. Aristotle crossed the Aegean to Assos at the invitation of Hermias, ruler of Atarneus and a former fellow student, taught there for about three years and married Pythias, Hermias's niece or adopted daughter."],
        { sea: true, via: [[23.78, 37.72], [24.03, 37.55], [24.22, 37.8], [24.6, 37.93], [24.66, 38.05], [25.3, 38.75], [26.0, 39.4]] }),
      w(-345, 26.55, 39.11,
        ['米蒂利尼（莱斯沃斯岛）', '考察海洋生物', '亚里士多德移居对岸的莱斯沃斯岛，那里是他的学生和日后的继承人泰奥弗拉斯托斯的故乡。两人在岛上观察研究动植物约两年，他对潟湖中鱼类、章鱼、海胆的解剖和记录后来写进《动物志》，被视为生物学的开端。'],
        ['Mytilene (island of Lesbos)', 'Studies marine life on Lesbos', "Aristotle moved across the strait to Lesbos, home of his pupil and eventual successor Theophrastus, and the two spent about two years observing animals and plants. His dissections and notes on the fish, octopuses and sea urchins of the island's lagoon fed into the History of Animals and are often seen as the beginning of biology."],
        { sea: true, via: [[26.52, 39.33]], wiki: { zh: '莱斯沃斯岛', en: 'Lesbos' } }),
      w(-343, 22.52, 40.76,
        ['佩拉（马其顿都城）', '应腓力二世之召来到马其顿', '马其顿国王腓力二世邀请亚里士多德担任十三岁的王子亚历山大的老师。亚里士多德的父亲曾是马其顿王室御医，他本人幼时可能就到过这座宫廷。相传作为酬谢，腓力后来重建了被自己毁掉的斯塔基拉城。'],
        ['Pella (capital of Macedon)', 'Summoned to Macedon by Philip II', "King Philip II invited Aristotle to tutor his thirteen-year-old son Alexander. Aristotle's father had been physician to the Macedonian royal house, and he may have known the court as a boy. In return, tradition says, Philip later rebuilt Stagira, which he had destroyed a few years earlier."],
        { sea: true, via: [[26.62, 38.97], [26.1, 38.8], [24.75, 39.2], [23.75, 39.72], [23.15, 40.0], [22.85, 40.35]] }),
      w(-343, 22.07, 40.62,
        ['米埃扎（今希腊纳乌萨附近）', '受腓力二世之邀教导少年亚历山大', '授课地点设在远离宫廷的米埃扎水泽仙女圣所，据说同学中有托勒密、赫费斯提翁等马其顿贵族子弟。亚里士多德讲授文学、伦理与政治，相传还为亚历山大校订了一部《伊利亚特》，亚历山大东征时一直带在身边。'],
        ['Mieza (near Naousa, Greece)', 'Tutors the young Alexander', "Lessons were held away from court at the sanctuary of the Nymphs at Mieza, where Alexander's classmates are said to have included future generals such as Ptolemy and Hephaestion. Aristotle taught literature, ethics and politics, and reputedly prepared an annotated copy of the Iliad that Alexander carried with him on campaign."]),
      w(-340, 23.79, 40.53,
        ['斯塔基拉', '授课结束，返回故乡', '前340年腓力出征，十六岁的亚历山大留守摄政，学业就此结束。亚里士多德此后几年大约住在重建的故乡斯塔基拉，继续与泰奥弗拉斯托斯等人从事研究；其间马其顿在喀罗尼亚击败希腊联军，确立了对希腊的霸权。'],
        ['Stagira', 'Returns home when the lessons end', "In 340 BCE Philip left on campaign and the sixteen-year-old Alexander became regent, ending his schooling. Aristotle seems to have spent the next years in his rebuilt home town of Stagira, continuing his research with Theophrastus, while Macedon's victory at Chaeronea made it master of Greece."]),
      w(-335, 23.7275, 37.9838,
        ['雅典', '创办吕克昂学园，著述讲学', '亚历山大即位后，亚里士多德回到雅典，在城东阿波罗圣林旁的吕克昂体育场办学。他习惯边散步边讲课，学派因此得名“逍遥学派”。此后十二年间他组织学生搜集各城邦政制和动植物资料，现存著作多出自这一时期的讲稿。'],
        ['Athens', 'Founds the Lyceum', "After Alexander's accession Aristotle returned to Athens and set up a school in the gymnasium of the Lyceum, east of the city. He lectured while walking its colonnades, which gave his followers the name Peripatetics. Over twelve years he directed research into constitutions, animals and plants; most of his surviving works derive from lecture notes of this period."],
        { sea: true, via: [[24.2, 40.52], [24.55, 40.1], [24.95, 39.2], [24.85, 38.45], [24.66, 38.05], [24.6, 37.93], [24.22, 37.8], [24.03, 37.55], [23.78, 37.72]], wiki: { zh: '逍遥学派', en: 'Peripatetic school' } }),
      w(-323, 23.7275, 37.9838,
        ['雅典', '亚历山大去世，被控“不敬神”', '亚历山大病逝的消息传来，雅典掀起反马其顿浪潮，与马其顿渊源深厚的亚里士多德被人控以“不敬神”之罪。相传他说不愿让雅典人“第二次对哲学犯罪”（第一次指处死苏格拉底），把学园托付给泰奥弗拉斯托斯后离城。'],
        ['Athens', "Charged with impiety after Alexander's death", "News of Alexander's death set off an anti-Macedonian reaction in Athens, and Aristotle, with his close ties to Macedon, was indicted for impiety. Saying, by tradition, that he would not let the Athenians 'sin twice against philosophy' (the first time being the execution of Socrates), he entrusted the Lyceum to Theophrastus and left."]),
      w(-322, 23.6, 38.46,
        ['卡尔基斯（优卑亚岛）', '避居卡尔基斯，次年病逝', '亚里士多德退居母亲家族在优卑亚岛卡尔基斯的产业，前322年因胃病去世，终年六十二岁。他的遗嘱保存在第欧根尼·拉尔修的著作中，其中安排了家人的生活，并吩咐释放数名奴隶。'],
        ['Chalcis (island of Euboea)', 'Dies in retirement at Chalcis', "Aristotle withdrew to his mother's family estate at Chalcis on Euboea and died there in 322 BCE, reportedly of a stomach ailment, aged sixty-two. His will, preserved by Diogenes Laertius, provides for his household and frees several of his slaves."],
        { wiki: { zh: '哈尔基斯', en: 'Chalcis' } }),
    ],
    wiki: { zh: '亚里士多德', en: 'Aristotle' },
  },
  {
    id: 'alexander',
    name: { zh: '亚历山大大帝', en: 'Alexander the Great' },
    birth: -356, death: -323,
    title: { zh: '马其顿国王、军事统帅', en: 'King of Macedon and military commander' },
    region: 'europe', sprite: 'horse',
    summary: {
      zh: '马其顿国王，古代最著名的军事统帅之一。少年时师从亚里士多德，二十岁即位后率军东征，十年间征服波斯帝国、埃及与中亚，兵锋直抵印度河流域，建立起横跨欧亚非的庞大帝国，并建立了多座以其名字命名的城市。他三十二岁病逝于巴比伦，帝国随即分裂，但希腊文化随之广布东方，开启了“希腊化时代”。',
      en: 'King of Macedon and one of the most celebrated commanders of antiquity. Taught by Aristotle as a boy, he came to the throne at twenty and led his army east; in ten years he conquered the Persian Empire, Egypt and Central Asia and reached the Indus valley, creating an empire that spanned Europe, Asia and Africa and founding many cities named after himself. He died at Babylon aged thirty-two and his empire soon broke apart, but Greek culture spread across the East in its wake, opening the Hellenistic age.',
    },
    route: [
      w(-356, 22.52, 40.76,
        ['佩拉（马其顿都城，今希腊北部）', '生于马其顿都城佩拉', '亚历山大是国王腓力二世与伊庇鲁斯公主奥林匹娅斯之子。此时腓力正把马其顿从希腊北陲的小邦改造成军事强国，创建了使用长矛的马其顿方阵。相传亚历山大少年时驯服了无人能骑的烈马布西发拉斯，此马后来随他一路东征。'],
        ['Pella (capital of Macedon, northern Greece)', 'Born at Pella, the Macedonian capital', 'Alexander was the son of King Philip II and Olympias, a princess of Epirus. Philip was then turning Macedon from a marginal northern kingdom into a military power built around the pike phalanx. As a boy Alexander is said to have tamed the unridable horse Bucephalus, which carried him throughout his campaigns.']),
      w(-343, 22.07, 40.62,
        ['米埃扎（今希腊纳乌萨附近）', '师从亚里士多德', '十三岁起，亚历山大在米埃扎跟随亚里士多德学习了约三年，内容包括哲学、文学、医学和政治。他终生喜爱荷马史诗，以阿喀琉斯为榜样；东征时还带着学者同行，记录各地的山川物产。'],
        ['Mieza (near Naousa, Greece)', 'Taught by Aristotle', 'From the age of thirteen Alexander studied for about three years under Aristotle at Mieza, reading philosophy, literature, medicine and politics. He loved Homer all his life and took Achilles as his model, and he later took scholars with him to Asia to record its lands, plants and animals.']),
      w(-338, 22.84, 38.49,
        ['喀罗尼亚（希腊中部）', '十八岁指挥左翼，击溃底比斯圣队', '腓力二世在喀罗尼亚迎战雅典与底比斯联军，十八岁的亚历山大指挥马其顿军左翼，相传是他率先突破敌阵，歼灭了号称不败的底比斯“圣队”。此战确立了马其顿对希腊的霸权，次年腓力组建科林斯同盟，准备讨伐波斯。'],
        ['Chaeronea (central Greece)', 'Commands the left wing at eighteen', 'When Philip II met the allied armies of Athens and Thebes at Chaeronea, the eighteen-year-old Alexander commanded the Macedonian left and is credited with breaking the line and destroying the Theban Sacred Band. The victory made Macedon master of Greece, and the next year Philip formed the League of Corinth to make war on Persia.']),
      w(-336, 22.32, 40.48,
        ['艾盖（马其顿旧都，今希腊韦尔吉纳）', '父王腓力二世遇刺，即位为王', '腓力二世在女儿婚礼的庆典上于艾盖剧场被侍卫保萨尼亚斯刺杀，二十岁的亚历山大被军队拥立为王。他迅速清除王位竞争者，次年北征至多瑙河，随后夷平起兵反叛的底比斯，震慑全希腊，接掌了讨伐波斯的统帅权。'],
        ['Aigai (old Macedonian capital, now Vergina, Greece)', 'Becomes king after the murder of Philip II', "Philip II was stabbed by one of his bodyguards in the theatre at Aigai during his daughter's wedding festival, and the army acclaimed the twenty-year-old Alexander king. He removed his rivals, campaigned as far as the Danube, and in 335 BCE razed rebellious Thebes, cowing Greece and securing command of the war against Persia."]),
      w(-334, 27.25, 40.2,
        ['格拉尼库斯河（今土耳其比加河）', '渡赫勒斯滂海峡，首战击败波斯', '亚历山大率不到四万步骑渡过赫勒斯滂海峡，先到特洛伊凭吊阿喀琉斯之墓，随后在格拉尼库斯河畔强渡击败波斯总督联军。混战中他的头盔被劈裂，幸得“黑”克利图斯出手相救。此后小亚细亚西部诸城纷纷归降。'],
        ['Granicus river (now the Biga river, Turkey)', 'Crosses the Hellespont and wins his first battle', 'Alexander crossed the Hellespont with fewer than 40,000 men, paid homage at the tomb of Achilles at Troy, then forced the Granicus against the army of the Persian satraps. In the melee his helmet was split and Cleitus the Black saved his life. The Greek cities of western Asia Minor then opened their gates.'],
        { via: [[23.85, 40.82], [25.6, 40.95], [26.75, 40.75], [26.85, 40.58], [26.6, 40.42], [26.4, 40.2], [26.24, 39.96]] }),
      w(-333, 31.99, 39.65,
        ['戈尔狄翁（弗里吉亚古都，今土耳其波拉特勒附近）', '挥剑斩断“戈尔狄俄斯之结”', '亚历山大沿小亚细亚海岸南下，攻克哈利卡纳苏斯后北上弗里吉亚，在戈尔狄翁过冬整军。当地神庙里有一辆古车，车辕上系着无人能解的绳结，传说解开者将成为亚洲之主。按最流行的说法，他拔剑一挥将绳结斩开。'],
        ['Gordium (old Phrygian capital, near Polatli, Turkey)', 'Cuts the Gordian knot', 'After taking Halicarnassus and the southern coast, Alexander marched inland to Gordium to regroup. An ancient wagon there was bound to its yoke by an intricate knot, and legend promised rule over Asia to whoever undid it. By the best-known account he simply sliced it through with his sword.'],
        { via: [[28.04, 38.49], [27.34, 37.94], [27.42, 37.04], [30.85, 36.96], [30.17, 38.07]], wiki: { zh: '戈耳狄俄斯之结', en: 'Gordian Knot' } }),
      w(-333, 36.2, 36.85,
        ['伊苏斯（今土耳其伊斯肯德伦湾北岸）', '大败大流士三世', '大流士三世亲率大军绕到亚历山大背后，两军在山海之间的狭窄平原上交战，波斯军的兵力优势无从施展。亚历山大率骑兵直冲大流士所在的中军，大流士弃车而逃，母亲、妻子和女儿都成了俘虏，受到亚历山大的礼遇。'],
        ['Issus (north shore of the Gulf of Iskenderun, Turkey)', 'Defeats Darius III', "Darius III led a large army across Alexander's rear, but the narrow plain between the mountains and the sea cancelled the Persian advantage in numbers. Alexander charged straight at the Persian centre and Darius fled, leaving his mother, wife and daughters to be captured; Alexander treated them with honour."],
        { via: [[32.85, 39.93], [34.8, 37.28], [34.9, 36.92]], wiki: { zh: '伊苏斯战役', en: 'Battle of Issus' } }),
      w(-332, 35.2, 33.27,
        ['推罗（今黎巴嫩苏尔）', '围攻七个月攻克推罗', '腓尼基诸城多不战而降，唯独建在离岸岛屿上的推罗闭门拒守。亚历山大下令修筑一条近一公里长的堤道通向岛城，并调集腓尼基和塞浦路斯舰队助战，历时七个月破城。堤道后来泥沙淤积，推罗从此与大陆相连。'],
        ['Tyre (now Sur, Lebanon)', 'Takes Tyre after a seven-month siege', 'Most Phoenician cities surrendered, but Tyre, built on an island off the coast, shut its gates. Alexander had a causeway nearly a kilometre long built out to the walls and brought up Phoenician and Cypriot fleets, taking the city after seven months. Silt gathered around the mole, and Tyre has been joined to the mainland ever since.'],
        { via: [[36.2, 36.0], [36.0, 34.6]] }),
      w(-331, 29.92, 31.2,
        ['亚历山大里亚（今埃及亚历山大港）', '进入埃及，建亚历山大城', '波斯的埃及总督不战而降，亚历山大在孟菲斯被埃及人奉为法老。他在尼罗河三角洲西端、地中海与马留提斯湖之间亲自选定城址，建立亚历山大城。这座城市后来成为托勒密王朝的都城和地中海世界的学术中心。'],
        ['Alexandria (Egypt)', 'Enters Egypt and founds Alexandria', 'The Persian satrap surrendered Egypt without a fight, and Alexander was welcomed at Memphis as pharaoh. On a strip of land between the Mediterranean and Lake Mareotis, west of the Nile delta, he marked out a new city himself. Alexandria later became the Ptolemaic capital and the intellectual centre of the Mediterranean world.'],
        { via: [[34.45, 31.5], [33.8, 31.05], [32.55, 30.95], [31.25, 29.85]] }),
      w(-331, 25.52, 29.2,
        ['锡瓦绿洲（埃及西部沙漠）', '朝拜阿蒙神谕', '亚历山大带少数随从沿海岸西行，再向南穿越约三百公里的沙漠，到锡瓦绿洲求问阿蒙神谕。祭司称他为“阿蒙之子”，至于他问了什么、得到什么答复，他从未公开。此后他常以宙斯—阿蒙之子自居，后世钱币上的亚历山大像也带有公羊角。'],
        ['Siwa Oasis (Western Desert, Egypt)', 'Consults the oracle of Amun', "With a small escort Alexander followed the coast west and then crossed some 300 km of desert to the oracle of Amun at Siwa. The priest greeted him as son of Amun; what he asked and was told he never revealed. He later styled himself son of Zeus-Ammon, and posthumous coin portraits show him with ram's horns."],
        { via: [[28.9, 30.75], [27.9, 31.0], [27.2, 31.2]], wiki: { zh: '锡瓦绿洲', en: 'Siwa Oasis' } }),
      w(-331, 43.25, 36.57,
        ['高加米拉（今伊拉克埃尔比勒附近）', '决战击溃波斯大军', '大流士三世在平原上集结了包括卷镰战车和战象在内的大军，亚历山大以约四万七千人迎战。他率伙伴骑兵斜向右翼运动，趁波斯阵线出现缺口时直扑大流士，大流士再次逃走，全军崩溃。此战后亚历山大被拥为“亚洲之王”。'],
        ['Gaugamela (near Erbil, Iraq)', 'Routs the Persian army in the decisive battle', 'Darius III had drawn up a huge army with scythed chariots and elephants on level ground; Alexander had about 47,000 men. Leading the Companion cavalry obliquely to the right, he drove into a gap that opened in the Persian line and made for Darius, who fled again as his army broke. Alexander was acclaimed King of Asia.'],
        { via: [[31.25, 29.85], [32.55, 30.95], [33.8, 31.05], [34.45, 31.5], [35.2, 32.6], [35.25, 33.27], [38.5, 35.9]], event: 'battle-of-gaugamela' }),
      w(-331, 44.42, 32.54,
        ['巴比伦（今伊拉克希拉附近）', '进入巴比伦', '波斯总督马扎亚斯献城投降，居民夹道以鲜花和香料迎接。亚历山大下令修复马尔杜克神庙，并留用马扎亚斯继续担任总督，开始起用波斯旧臣。随后他东进苏萨，接收了波斯王室积存的巨额金银。'],
        ['Babylon (near Hillah, Iraq)', 'Enters Babylon', 'The satrap Mazaeus surrendered the city and its people lined the streets with flowers and incense. Alexander ordered the temple of Marduk restored and kept Mazaeus as governor, the first of many Persian nobles he retained. He then moved on to Susa and took possession of the vast royal treasure stored there.'],
        { wiki: { zh: '巴比伦', en: 'Babylon' } }),
      w(-330, 52.89, 29.93,
        ['波斯波利斯（今伊朗设拉子东北）', '焚毁波斯王宫', '亚历山大突破“波斯门”山口，占领阿契美尼德王朝的礼仪之都，在此停留约四个月。离开前，薛西斯的宫殿在一场酒宴后被付之一炬。古代作家或说这是报复波斯人当年焚毁雅典卫城，或说是醉后受雅典女子泰伊丝怂恿。'],
        ['Persepolis (northeast of Shiraz, Iran)', 'Burns the Persian royal palace', 'Forcing the pass of the Persian Gates, Alexander took the ceremonial capital of the Achaemenids and stayed about four months. Before he left, the palace of Xerxes went up in flames after a banquet: ancient writers call it either revenge for the burning of the Athenian Acropolis or a drunken whim urged on by the courtesan Thais.'],
        { via: [[48.26, 32.19]], wiki: { zh: '波斯波利斯', en: 'Persepolis' } }),
      w(-330, 54.05, 35.96,
        ['赫卡通皮洛斯附近（今伊朗达姆甘一带）', '追及大流士，波斯王已遇害', '亚历山大从埃克巴坦那出发，昼夜兼程追赶东逃的大流士。巴克特里亚总督贝苏斯等人先已劫持并刺伤了大流士，亚历山大赶到时只见到遗体。他以王礼将其归葬波斯波利斯，自居为阿契美尼德王朝的继承者，继续追讨弑君者。'],
        ['Near Hecatompylos (around Damghan, Iran)', 'Overtakes Darius, already murdered', 'Alexander rode day and night from Ecbatana in pursuit of the fleeing Darius, only to find that Bessus, satrap of Bactria, and other nobles had stabbed their king and left him dying. Alexander sent the body to Persepolis for a royal burial and, presenting himself as the legitimate successor of the Achaemenids, set out after the regicides.'],
        { via: [[48.52, 34.8], [51.44, 35.59]] }),
      w(-329, 66.9, 36.76,
        ['巴克特拉（今阿富汗巴尔赫）', '征服巴克特里亚', '亚历山大绕道今阿富汗南部，于早春翻越积雪的兴都库什山进入巴克特里亚。自立为王的贝苏斯烧毁乡野、退过阿姆河，不久被部下出卖，后被处死。巴克特拉此后成为亚历山大在中亚的大本营。'],
        ['Bactra (now Balkh, Afghanistan)', 'Conquers Bactria', "Alexander swung through what is now southern Afghanistan and crossed the snowbound Hindu Kush in early spring. Bessus, who had proclaimed himself king, laid waste the countryside and withdrew beyond the Oxus, where his own officers gave him up; he was later executed. Bactra became Alexander's base in Central Asia."],
        { via: [[62.2, 34.35], [65.7, 31.62], [69.3, 34.99]] }),
      w(-329, 66.96, 39.65,
        ['马拉坎达（今乌兹别克斯坦撒马尔罕）', '平定索格底亚那', '亚历山大渡过阿姆河占领粟特首府马拉坎达，却陷入斯皮塔米尼斯领导的游击战，苦战两年才平定此地。前328年他在这里的酒宴上醉后刺死了曾救过自己性命的克利图斯；次年迎娶当地贵族之女罗克珊娜，以笼络豪族。'],
        ['Maracanda (now Samarkand, Uzbekistan)', 'Subdues Sogdiana', 'Alexander crossed the Oxus and took Maracanda, the Sogdian capital, but was drawn into two years of guerrilla war led by Spitamenes. Here in 328 BCE he killed Cleitus, who had saved his life at the Granicus, in a drunken quarrel; the next year he married Roxana, daughter of a local noble, to win over the aristocracy.']),
      w(-329, 69.63, 40.28,
        ['极远亚历山大里亚（今塔吉克斯坦苦盏）', '在锡尔河畔建城，东征的东北极限', '亚历山大推进到波斯帝国的东北边界药杀水（今锡尔河），在河边用约二十天筑起一座新城，安置希腊雇佣兵和伤残老兵，名为“极远的亚历山大里亚”。他还渡河击退了对岸的塞人骑兵，这里是他东征所到的东北极限。'],
        ['Alexandria Eschate (now Khujand, Tajikistan)', 'Founds his "farthest" city on the Jaxartes', "Reaching the Jaxartes (Syr Darya), the north-eastern limit of the Persian Empire, Alexander had a walled city built in about twenty days and settled it with Greek mercenaries and unfit veterans: Alexandria Eschate, 'the Farthest'. He also crossed the river to drive off Scythian horsemen. It marked the north-eastern limit of his conquests."]),
      w(-326, 73.6, 32.9,
        ['希达斯皮斯河（今巴基斯坦杰赫勒姆河）', '击败印度国王波鲁斯', '亚历山大越过兴都库什山和印度河，在塔克西拉受到当地国王款待，随后趁雨季的风雨之夜偷渡希达斯皮斯河，击败拥有大批战象的国王波鲁斯。波鲁斯被俘后要求“像国王那样”被对待，亚历山大让他继续统治并扩大了他的领地。'],
        ['Hydaspes river (now the Jhelum, Pakistan)', 'Defeats the Indian king Porus', "Having crossed the Hindu Kush and the Indus and been received at Taxila, Alexander slipped across the swollen Hydaspes on a stormy night and defeated King Porus and his many war elephants. Asked how he wished to be treated, the captured Porus answered 'like a king'; Alexander restored and enlarged his kingdom."],
        { via: [[66.96, 39.65], [66.9, 36.76], [69.3, 34.99], [71.5, 34.0], [72.83, 33.75]], wiki: { zh: '希达斯皮斯河战役', en: 'Battle of the Hydaspes' } }),
      w(-326, 75.3, 31.6,
        ['希发西斯河（今印度比亚斯河，位置约略）', '将士拒绝前进，东征止步', '大军冒着季风暴雨东进到希发西斯河，传闻对岸还有拥有大量战象的强国。离家八年的马其顿士兵拒绝再向前走，老将科埃努斯代众人陈情。亚历山大在营帐中独处三日后让步，下令在河边筑起十二座祭坛，然后回师。'],
        ['Hyphasis river (now the Beas, India; location approximate)', 'The army refuses to go further', 'Marching east through the monsoon rains, the army reached the Hyphasis amid reports of powerful kingdoms with great elephant forces beyond. After eight years away the Macedonians would go no further, and the veteran general Coenus spoke for them. Alexander shut himself in his tent for three days, then gave way, raised twelve altars on the bank and turned back.']),
      w(-325, 71.47, 30.2,
        ['马利人的城寨（一般认为在今巴基斯坦木尔坦一带）', '攻城时身负重伤', '亚历山大造船沿希达斯皮斯河、印度河顺流南下，沿途征讨两岸部族。进攻马利人的一座城寨时，他率先登上城墙并跳入城内，被一箭射穿胸甲、伤及肺部，险些丧命。军中一度盛传他已阵亡，直到他抱伤乘船在将士面前露面。'],
        ['Citadel of the Malli (probably near Multan, Pakistan)', 'Gravely wounded storming a town', 'Alexander built a fleet and moved down the Hydaspes and Indus, subduing the peoples along the banks. Storming a town of the Malli, he was first onto the wall and leapt down inside almost alone; an arrow pierced his cuirass and lung. Rumours of his death spread through the army until he showed himself, still weak, from a boat.'],
        { via: [[73.6, 32.9], [72.3, 31.2]] }),
      w(-325, 62.5, 26.2,
        ['格德罗西亚沙漠（今巴基斯坦、伊朗的莫克兰地区）', '穿越沙漠西返，损失惨重', '到达印度河口后，亚历山大命尼阿库斯率舰队沿海岸驶向波斯湾，自己带陆军穿越格德罗西亚沙漠。约六十天的行军中酷热缺水，随军的妇孺和驮畜死亡甚多。相传有士兵用头盔盛来一点水，他当众倒掉，以示与全军同甘共苦。'],
        ['Gedrosian Desert (the Makran, Pakistan and Iran)', 'Costly desert march back to the west', 'From the mouth of the Indus Alexander sent Nearchus with the fleet along the coast to the Persian Gulf and led the army through the Gedrosian desert. In about sixty days of heat and thirst many camp followers and pack animals died. Offered a helmet of water, he is said to have poured it away in front of his men.'],
        { via: [[68.37, 25.39], [66.6, 25.8]] }),
      w(-324, 48.26, 32.19,
        ['苏萨（今伊朗胡齐斯坦省舒什）', '举行马其顿人与波斯人的集体婚礼', '回到波斯腹地后，亚历山大惩办了一批趁他远征而贪暴的总督。在苏萨，他按波斯礼仪迎娶大流士三世之女斯妲特拉，约八十名将领同时与波斯贵族女子成婚；他又编练三万名波斯青年入伍，试图融合两个民族，引起马其顿老兵不满。'],
        ['Susa (now Shush, Khuzestan, Iran)', 'Holds the mass wedding of Macedonians and Persians', 'Back in the Persian heartland, Alexander punished satraps who had misruled in his absence. At Susa he married Stateira, daughter of Darius III, in the Persian manner, while about eighty of his officers took Persian noblewomen as brides, and he enrolled 30,000 Persian youths in the army. His policy of fusion angered the Macedonian veterans.'],
        { via: [[53.17, 30.2]] }),
      w(-323, 44.42, 32.54,
        ['巴比伦', '病逝，年仅三十二岁', '前324年挚友赫费斯提翁病死于埃克巴坦那，亚历山大悲痛不已。回到巴比伦后，他正筹备环航阿拉伯半岛的远征，却在一次宴饮后发起高烧，十余日后于前323年6月去世。他没有留下明确的继承人，部将们随即为瓜分帝国而混战数十年。'],
        ['Babylon', 'Dies at the age of thirty-two', 'The death of his closest friend Hephaestion at Ecbatana in 324 BCE left Alexander distraught. Back in Babylon he was planning an expedition around Arabia when he fell into a fever after a banquet and died some ten days later, in June 323 BCE. He named no clear heir, and his generals fought over the empire for decades.'],
        { via: [[44.55, 33.2], [48.52, 34.8]] }),
    ],
    wiki: { zh: '亚历山大大帝', en: 'Alexander the Great' },
  },
  {
    id: 'ashoka',
    name: { zh: '阿育王', en: 'Ashoka' },
    birth: -304, death: -232, approx: true,
    title: { zh: '孔雀王朝君主', en: 'Mauryan emperor' },
    region: 'south-asia', lineage: 'india', sprite: 'horse',
    summary: {
      zh: '印度孔雀王朝第三代君主，旃陀罗笈多之孙，约前268—前232年在位。他治下的帝国北起今阿富汗，南抵德干高原南部，几乎囊括整个南亚次大陆。征服羯陵伽造成的惨重伤亡使他深感悔恨，转而信奉佛教，以“正法”治国，把诏令刻在岩壁和石柱上颁行全国，并遣使四方弘法，推动佛教从恒河流域的地方教派走向世界。他早年的事迹多出自后世佛教文献，年代均为约数。',
      en: "Third ruler of the Mauryan dynasty of India and grandson of its founder Chandragupta, reigning c. 268-232 BCE over an empire that stretched from present-day Afghanistan to the southern Deccan and covered nearly the whole subcontinent. Remorse at the bloodshed of his conquest of Kalinga turned him towards Buddhism and a policy of governing by dhamma (moral law), which he proclaimed in edicts carved on rocks and pillars across his realm. The missions he sponsored helped turn Buddhism from a regional movement into a world religion. Accounts of his early life come from later Buddhist texts, and all dates are approximate.",
    },
    route: [
      w(-304, 85.14, 25.61,
        ['华氏城（孔雀王朝都城，今印度巴特那）', '生于孔雀王朝都城', '阿育王是孔雀王朝第二代君主宾头娑罗之子、开国君主旃陀罗笈多之孙。华氏城位于恒河与宋河交汇处，据到访过的希腊使节麦加斯梯尼描述，城周有木栅和壕沟环绕，是当时世界上最大的城市之一。'],
        ['Pataliputra (Mauryan capital, now Patna, India)', 'Born in the Mauryan capital', "Ashoka was a son of Bindusara, the second Mauryan ruler, and grandson of the dynasty's founder Chandragupta. Pataliputra stood near the confluence of the Ganges and the Son; the Greek envoy Megasthenes described it as ringed by a timber palisade and a moat, and it was among the largest cities of its age."],
        { wiki: { zh: '华氏城', en: 'Pataliputra' } }),
      w(-287, 72.83, 33.75,
        ['塔克西拉（今巴基斯坦旁遮普省）', '相传奉父命平定塔克西拉叛乱', '据佛教文献《阿育王传》，西北重镇塔克西拉起兵反抗大臣的暴政，宾头娑罗派年轻的阿育王子前去平乱。当地居民表示只反贪官、不反国王，出城迎接，叛乱不战而平。这一记载带有传说色彩，年代也无从确知。'],
        ['Taxila (Punjab, Pakistan)', 'Said to have quelled a revolt at Taxila', 'According to the Buddhist Ashokavadana, the north-western city of Taxila rose against oppressive ministers and Bindusara sent the young prince Ashoka to restore order. The citizens came out to welcome him, saying their quarrel was with the officials and not the king. The story is legendary in tone and cannot be dated.'],
        { wiki: { zh: '塔克西拉', en: 'Taxila' } }),
      w(-286, 77.74, 23.48,
        ['毗底沙（今印度中央邦毗底沙、桑吉一带）', '赴任途中娶商人之女提毗', '斯里兰卡的《大史》记载，阿育王子前往优禅尼赴任途中在毗底沙停留，娶当地富商之女提毗，生下儿子摩哂陀和女儿僧伽蜜多。他即位后在毗底沙附近的桑吉山上建塔立柱，是今天桑吉大塔的前身。'],
        ['Vidisha (around Vidisha and Sanchi, Madhya Pradesh, India)', "Marries Devi, a merchant's daughter", 'The Sri Lankan chronicle Mahavamsa relates that on his way to Ujjain the prince stopped at Vidisha and married Devi, daughter of a local merchant, who bore him a son, Mahinda, and a daughter, Sanghamitta. As emperor he raised a stupa and pillar on the nearby hill of Sanchi, the core of the Great Stupa there today.']),
      w(-285, 75.78, 23.18,
        ['优禅尼（今印度中央邦乌贾因）', '出任阿槃提总督', '优禅尼是西部阿槃提地区的首府，扼守恒河平原通往西海岸港口的商路。按照斯里兰卡史书的说法，阿育王子在此担任总督多年，长子摩哂陀即出生于此，直到父王病重的消息传来。'],
        ['Ujjayini (now Ujjain, Madhya Pradesh, India)', 'Serves as viceroy of Avanti', 'Ujjain was the chief city of Avanti in the west, commanding the trade routes from the Ganges plain to the ports of the western coast. According to the Sri Lankan chronicles, Prince Ashoka governed here for some years and his son Mahinda was born here, until word came that his father was dying.']),
      w(-268, 85.14, 25.61,
        ['华氏城', '争位数年后正式即位', '宾头娑罗约于前272年去世，阿育王赶回都城，与兄弟争夺王位。佛教文献称他杀死了九十九个兄弟，显系夸张，但从父王去世到约前268年举行灌顶大典相隔数年，说明继位并不顺利。'],
        ['Pataliputra', 'Consecrated king after a contested succession', 'Bindusara died around 272 BCE and Ashoka hurried to the capital to contend with his brothers for the throne. Buddhist texts claim he killed ninety-nine of them, plainly an exaggeration, but the gap of several years before his consecration in about 268 BCE suggests that the succession was disputed.']),
      w(-261, 85.84, 20.19,
        ['羯陵伽（今印度奥里萨邦陀利一带）', '征服羯陵伽，深自悔恨', '即位第八年，阿育王出兵征服东海岸的羯陵伽国。他在第十三号摩崖法敕中自述，此役有十万人被杀、十五万人被掳走，死于战祸者更数倍于此，“天爱王”为此深感痛悔。此后他不再发动征服战争，宣称“法的胜利”才是真正的胜利。'],
        ['Kalinga (around Dhauli, Odisha, India)', 'Conquers Kalinga and is filled with remorse', "In his eighth regnal year Ashoka conquered Kalinga on the east coast. His Rock Edict XIII records that 100,000 people were killed, 150,000 deported and many more perished, and that the 'Beloved of the Gods' felt deep remorse. He fought no further wars of conquest and declared that the only true victory is victory by dhamma."],
        { event: 'kalinga-war' }),
      w(-259, 84.991, 24.696,
        ['菩提伽耶（今印度比哈尔邦）', '朝拜佛陀成道处', '第八号摩崖法敕记载，阿育王在即位第十年“前往三菩提”，即佛陀悟道之地，从此以巡访僧人、布施长老、向民众宣讲正法的“法巡”取代历代国王的游猎之行。相传菩提树下的金刚座和最早的寺庙即由他修建。'],
        ['Bodh Gaya (Bihar, India)', "Makes a pilgrimage to the site of the Buddha's enlightenment", "Rock Edict VIII records that in his tenth regnal year Ashoka 'went to Sambodhi', the place of the Buddha's awakening, and that from then on royal hunting trips gave way to 'dhamma tours' for visiting monks, giving alms and instructing the people. Tradition credits him with the first shrine and the Diamond Throne beneath the Bodhi tree."],
        { wiki: { zh: '摩诃菩提寺', en: 'Mahabodhi Temple' } }),
      w(-257, 85.14, 25.61,
        ['华氏城', '颁布摩崖法敕，以“正法”治国', '即位第十二、十三年前后，阿育王把一系列诏令刻在帝国各地的岩石上，西北边境甚至使用希腊文和阿拉美文。法敕倡导不杀生、孝顺父母、宽容各教派，宣布为人畜设立医疗、沿路植树掘井，并设“正法大官”巡行督导。'],
        ['Pataliputra', 'Issues the Rock Edicts and governs by dhamma', 'Around his twelfth and thirteenth regnal years Ashoka had a series of edicts cut into rock faces across the empire, on the north-western frontier even in Greek and Aramaic. They urge non-violence, respect for parents and tolerance among sects, announce medical care, wells and shade trees for people and animals, and create officers of dhamma to oversee it all.'],
        { wiki: { zh: '阿育王诏书', en: 'Edicts of Ashoka' } }),
      w(-250, 85.14, 25.61,
        ['华氏城', '相传主持第三次结集，遣使四方', '斯里兰卡史书记载，阿育王在华氏城请目犍连子帝须长老主持第三次结集，整顿僧团，随后派长老分赴各地传教，其子摩哂陀前往斯里兰卡。他本人的法敕则提到曾向叙利亚、埃及、马其顿等五位希腊化国王派出使者宣扬正法。'],
        ['Pataliputra', 'Third Buddhist council and missions abroad', 'The Sri Lankan chronicles say that Ashoka convened the Third Buddhist Council at Pataliputra under the elder Moggaliputta Tissa to purify the order, after which missionaries were sent out, his son Mahinda going to Sri Lanka. His own edicts speak of envoys of dhamma sent to five Hellenistic kings, including those of Syria, Egypt and Macedon.']),
      w(-249, 83.276, 27.469,
        ['蓝毗尼（今尼泊尔南部）', '亲临佛陀诞生地，立石柱', '即位第二十年，阿育王亲自来到蓝毗尼朝拜，立起一根石柱，并把当地村庄的田赋减为收成的八分之一。柱上铭文写明佛陀释迦牟尼诞生于此，1896年被重新发现，成为确认佛陀诞生地的关键证据。'],
        ['Lumbini (southern Nepal)', "Visits the Buddha's birthplace and sets up a pillar", "In his twentieth regnal year Ashoka came in person to worship at Lumbini, erected a stone pillar and cut the village's land tax to an eighth of the produce. Its inscription states that the Buddha Shakyamuni was born here; rediscovered in 1896, it settled the location of the birthplace."],
        { wiki: { zh: '蓝毗尼', en: 'Lumbini' } }),
      w(-249, 83.025, 25.381,
        ['鹿野苑（今印度瓦拉纳西附近的萨尔纳特）', '在初转法轮处立狮子柱', '相传阿育王曾在高僧优波毱多引导下巡礼各处佛迹。在佛陀初次说法的鹿野苑，他建塔立柱，柱上刻有告诫僧尼不得分裂僧团的诏令。石柱顶端的四狮柱头1950年被定为印度国徽，柱头上的法轮则出现在印度国旗中央。'],
        ['Sarnath (near Varanasi, India)', 'Raises the lion pillar where the Buddha first preached', 'Legend has Ashoka touring the holy places guided by the monk Upagupta. At Sarnath, where the Buddha first taught, he built a stupa and set up a pillar warning against schism in the order. Its capital of four lions became the national emblem of India in 1950, and the wheel carved on it appears on the Indian flag.'],
        { wiki: { zh: '阿育王狮子柱头', en: 'Lion Capital of Ashoka' } }),
      w(-242, 85.14, 25.61,
        ['华氏城', '晚年颁布石柱法敕', '即位第二十六、二十七年，阿育王又把七篇诏令刻在恒河平原各地的磨光石柱上，回顾自己推行正法的作为，并开列禁止宰杀的动物名单。此后的记载很少，佛教传说称他晚年倾尽国库布施僧团，被大臣和王孙限制了权力。'],
        ['Pataliputra', 'Issues the Pillar Edicts late in his reign', 'In his twenty-sixth and twenty-seventh regnal years Ashoka had seven further edicts inscribed on polished stone pillars across the Ganges plain, reviewing his work for dhamma and listing animals that might not be killed. Little is recorded after this; Buddhist legend has him emptying the treasury in gifts to the order until his ministers restrained him.']),
      w(-232, 85.14, 25.61,
        ['华氏城', '在位约三十七年后去世', '阿育王约于前232年去世。他死后帝国迅速衰落，约半个世纪后末代君主被部将弗沙蜜多罗·巽伽所杀，孔雀王朝灭亡。阿育王的事迹此后在印度渐被遗忘，直到1837年英国学者普林塞普释读出婆罗米文，他的法敕才重新为世人所知。'],
        ['Pataliputra', 'Dies after a reign of about thirty-seven years', 'Ashoka died around 232 BCE. His empire declined quickly, and some fifty years later the last Mauryan king was killed by his general Pushyamitra Shunga. Ashoka himself was largely forgotten in India until James Prinsep deciphered the Brahmi script in 1837 and his edicts could be read again.']),
    ],
    wiki: { zh: '阿育王', en: 'Ashoka' },
  },
  {
    id: 'qin-shi-huang',
    name: { zh: '秦始皇', en: 'Qin Shi Huang' },
    birth: -259, death: -210,
    title: { zh: '秦朝开国皇帝', en: 'First emperor of the Qin dynasty' },
    region: 'china', lineage: 'china', sprite: 'horse',
    summary: {
      zh: '秦朝开国皇帝，嬴姓赵氏，名政，中国历史上第一个称“皇帝”的君主。生于赵都邯郸，十三岁即秦王位，三十九岁灭六国完成统一，废分封、行郡县，统一文字、货币、度量衡，修驰道、筑长城，奠定了此后两千余年中央集权王朝的基本格局。统一后他五次出巡，最后病逝于途中；其严刑峻法与繁重徭役也加速了秦朝的灭亡。',
      en: 'Founder of the Qin dynasty and the first Chinese ruler to take the title of emperor (huangdi); personal name Zheng. Born in Handan, capital of Zhao, he became king of Qin at thirteen and by thirty-nine had conquered the six rival states and unified China. He replaced hereditary fiefs with centrally appointed commanderies and counties, standardised the script, coinage, weights and measures, and built roads and frontier walls, setting the pattern of the centralised empire for two thousand years. He made five great tours of his realm and died on the last; his harsh laws and heavy labour demands hastened the fall of his dynasty.',
    },
    route: [
      w(-259, 114.49, 36.61,
        ['邯郸（赵国都城，今河北邯郸）', '生于赵国都城邯郸，名政', '嬴政的父亲异人（后改名子楚）是秦国送到赵国的质子，母亲赵姬原是大商人吕不韦的姬妾。他出生前一年，秦军刚在长平坑杀赵军数十万，秦人在邯郸处境艰险；前257年秦军围城，子楚靠吕不韦重金贿赂逃回秦国，母子二人留在赵国躲藏。'],
        ['Handan (capital of Zhao, Hebei)', 'Born in Handan, capital of Zhao', "Zheng's father Yiren, later called Zichu, was a Qin prince held hostage in Zhao; his mother, Lady Zhao, had been a concubine of the rich merchant Lu Buwei. Qin had just slaughtered a Zhao army at Changping, and when Qin besieged Handan in 257 BCE Zichu escaped with Lu's help, leaving mother and child in hiding."]),
      w(-246, 108.86, 34.38,
        ['咸阳（秦国都城，今陕西咸阳）', '十三岁即秦王位', '前251年秦昭襄王去世，赵国把嬴政母子送回秦国。父亲庄襄王在位仅三年便去世，十三岁的嬴政继位，国政由相邦吕不韦和太后主持。即位之初就开始在骊山为他营建陵墓，郑国渠也在此时动工。'],
        ['Xianyang (capital of Qin, Shaanxi)', 'Becomes king of Qin at thirteen', 'After King Zhaoxiang of Qin died in 251 BCE, Zhao sent Zheng and his mother back to Qin. His father reigned only three years, and Zheng succeeded at thirteen, with the chancellor Lu Buwei and the queen dowager governing for him. Work on his tomb at Mount Li began at once, as did the Zhengguo Canal.']),
      w(-238, 107.38, 34.52,
        ['雍城（秦国旧都，今陕西凤翔）', '行冠礼亲政，平定嫪毐之乱', '二十二岁的秦王到旧都雍城的蕲年宫举行冠礼。太后的宠臣嫪毐盗用玺印发兵作乱，秦王命昌平君等率军在咸阳击溃叛军，车裂嫪毐。次年吕不韦受牵连免相，后饮鸩自尽，秦王从此独揽大权，重用李斯、尉缭等人。'],
        ['Yong (old Qin capital, now Fengxiang, Shaanxi)', "Comes of age and crushes Lao Ai's revolt", "At twenty-two the king went to the old capital Yong for his capping ceremony. Lao Ai, the queen dowager's favourite, used forged seals to raise troops in revolt; the king's forces routed them at Xianyang and Lao Ai was torn apart by chariots. Lu Buwei was dismissed the next year and later took poison, leaving Zheng in sole command."]),
      w(-228, 114.49, 36.61,
        ['邯郸', '灭赵后重返出生地', '王翦率秦军攻破邯郸、俘虏赵王迁，秦王亲自来到这座自己出生的城市。据《史记》，他把当年与母亲家有仇怨的人全部坑杀，然后经太原、上郡返回咸阳。此前两年韩国已亡，秦灭六国的战争进入高潮。'],
        ['Handan', 'Returns to his birthplace after the fall of Zhao', "When Wang Jian took Handan and captured the king of Zhao, the king of Qin came in person to the city of his birth. According to the Records of the Grand Historian he put to death everyone who had wronged his mother's family there, then went home by way of Taiyuan. Han had fallen two years earlier."]),
      w(-227, 108.86, 34.38,
        ['咸阳', '荆轲刺秦王', '燕太子丹派荆轲以献督亢地图和秦国叛将樊於期首级为名入秦。在咸阳宫大殿上，图穷匕见，荆轲抓住秦王衣袖行刺，秦王挣断衣袖绕柱而逃，经侍臣提醒才拔出长剑砍倒荆轲。秦王大怒，立即增兵攻燕，次年攻克燕都蓟城。'],
        ['Xianyang', 'Survives the assassination attempt by Jing Ke', "Crown Prince Dan of Yan sent Jing Ke to Qin, ostensibly to present a map and a defector's head. As the map was unrolled a dagger appeared; Jing Ke seized the king's sleeve, but it tore, and the king dodged around a pillar until he could draw his sword and cut him down. Qin took the Yan capital next year."],
        { via: [[112.55, 37.87], [109.8, 37.95]], wiki: { zh: '荆轲', en: 'Jing Ke' } }),
      w(-224, 114.88, 33.73,
        ['郢陈（楚国旧都，今河南淮阳）', '亲临灭楚前线', '李信率二十万人伐楚大败后，秦王亲赴频阳向老将王翦道歉，按他的要求交出六十万大军。王翦坚壁不战，待楚军东撤时一举击溃。据《史记·秦始皇本纪》，楚王被俘后，秦王来到楚国旧都郢陈巡视；次年楚国残余势力被肃清。'],
        ['Yingchen (former Chu capital, now Huaiyang, Henan)', 'Visits the front in the conquest of Chu', "After Li Xin's 200,000 men were routed by Chu, the king apologised in person to the veteran Wang Jian and gave him the 600,000 troops he demanded. Wang Jian waited behind his ramparts, then shattered the Chu army as it withdrew. With the king of Chu a prisoner, the king of Qin visited the old Chu capital at Chen."]),
      w(-221, 108.86, 34.38,
        ['咸阳', '灭六国，称始皇帝', '王贲率军自燕地南下攻入临淄，齐王建投降，六国尽灭。秦王认为“王”号不足以称其功业，兼采“皇”“帝”之名自称“始皇帝”。他采纳李斯的意见，分天下为三十六郡，收缴民间兵器铸成十二金人，统一文字、度量衡和车轨。'],
        ['Xianyang', 'Completes the conquest and takes the title First Emperor', "When Wang Ben took Linzi and the king of Qi surrendered, the last of the six states was gone. Judging 'king' too small a title, Zheng styled himself Shi Huangdi, First Emperor. On Li Si's advice he divided the realm into thirty-six commanderies, cast the weapons of the conquered into twelve bronze colossi, and standardised script, measures and axle widths."],
        { event: 'qin-unification' }),
      w(-220, 106.4, 35.52,
        ['陇西、北地（鸡头山，今宁夏、甘肃六盘山一带）', '首次出巡，西至陇西、北地', '统一次年，始皇帝第一次出巡，目的地是秦人发祥的西部故土。他经陇西、北地两郡，登上鸡头山，取道回中返回咸阳。同年开始修筑以咸阳为中心、通往东方和南方的驰道。鸡头山的具体位置有不同说法。'],
        ['Longxi and Beidi (Mount Jitou, in the Liupan range of Ningxia and Gansu)', 'First tour: west to Longxi and Beidi', 'The year after unification the emperor made his first tour, through the old Qin homeland in the west. He crossed the commanderies of Longxi and Beidi, climbed Mount Jitou and returned by way of Huizhong. That year work began on the imperial highways radiating from Xianyang to the east and south. The exact site of Mount Jitou is uncertain.'],
        { via: [[103.86, 35.38]] }),
      w(-219, 117.1, 36.25,
        ['泰山（今山东泰安）', '东巡，封禅泰山', '始皇帝第二次出巡，先登峄山刻石颂秦功德，再到泰山下召集齐鲁儒生商议封禅礼仪。儒生众说纷纭，他索性自定仪式，从南坡乘车登顶祭天，下山时遇暴风雨，在一棵树下避雨，后封此树为“五大夫”。'],
        ['Mount Tai (now Tai\'an, Shandong)', 'Tours the east and performs the Feng and Shan sacrifices', 'On his second tour the emperor set up a stele on Mount Yi, then summoned the scholars of Qi and Lu to advise on the Mount Tai sacrifices. Finding them hopelessly divided, he devised his own rite and drove up the south face to worship Heaven; caught by a storm on the descent, he ennobled the tree that sheltered him.'],
        { via: [[108.86, 34.38], [112.45, 34.62], [117.0, 35.4]], wiki: { zh: '泰山', en: 'Mount Tai' } }),
      w(-219, 119.96, 35.65,
        ['琅琊（今山东青岛黄岛区琅琊台）', '登琅琊台，立琅琊刻石', '始皇帝沿渤海南岸东行，登成山、之罘，再南下琅琊。他十分喜爱这里，停留三个月，迁来三万户百姓，筑琅琊台并立石颂德。齐人徐巿（徐福）上书说海中有蓬莱等三座神山，他便派徐巿率数千童男童女入海求仙。'],
        ['Langya (Langya Terrace, Qingdao, Shandong)', 'Builds the Langya Terrace and sets up a stele', 'The emperor followed the coast to the tip of the Shandong peninsula and south to Langya, which so pleased him that he stayed three months, moved in 30,000 households and built a terrace. Told by Xu Fu of Qi of three spirit mountains in the sea, he sent him out with thousands of boys and girls to find them.'],
        { via: [[119.3, 36.8], [120.5, 37.3], [121.3, 37.45]] }),
      w(-219, 113.0, 29.36,
        ['湘山（今湖南岳阳洞庭湖君山）', '南巡至洞庭，怒伐湘山树', '归途中始皇帝先到彭城，派千人潜入泗水打捞周鼎，一无所获。随后他渡淮河、经南郡，乘船在洞庭湖遇上大风，几乎不能渡。听说湘山祠供奉的是尧女舜妻，他大怒，命三千刑徒砍光山上的树木，然后经武关回咸阳。'],
        ['Mount Xiang (Junshan Island in Dongting Lake, Yueyang, Hunan)', 'Reaches Dongting Lake and strips Mount Xiang', 'On the way home the emperor had a thousand men dive in the Si river at Pengcheng for the lost Zhou tripods, in vain. Crossing the Huai, he sailed onto Dongting Lake, where a gale nearly stopped him. Told that the shrine on Mount Xiang honoured the daughters of Yao, he had 3,000 convicts fell every tree on the hill.'],
        { via: [[117.19, 34.26], [112.19, 30.35]] }),
      w(-218, 114.05, 34.95,
        ['博浪沙（今河南原阳）', '东巡途中遭张良等人狙击', '第三次出巡途经阳武博浪沙时，韩国贵族后裔张良雇来的大力士投出一百二十斤重的铁椎，却误中副车。始皇帝大为震怒，下令全国大搜捕十天，未能抓到刺客。张良改名换姓逃亡下邳，后来成为刘邦的重要谋士。'],
        ['Bolangsha (now Yuanyang, Henan)', 'Ambushed by Zhang Liang on the road east', 'As the third tour passed Bolangsha, a strongman hired by Zhang Liang, a nobleman of the fallen state of Han, hurled a heavy iron hammer at the procession but struck an escort carriage. The furious emperor ordered a ten-day manhunt, without success. Zhang Liang went into hiding and later became chief adviser to Liu Bang, founder of the Han dynasty.'],
        { via: [[110.35, 33.55], [108.86, 34.38]] }),
      w(-218, 121.39, 37.6,
        ['之罘（今山东烟台芝罘岛）', '再登之罘，刻石纪功', '遇刺之后始皇帝照常东行，再次登上伸入海中的之罘山，立下两方刻石，称颂自己“周定四极”“经纬天下”。随后他又到琅琊，取道上党返回咸阳。之罘刻石原石早已不存，文字因《史记》的抄录而流传下来。'],
        ['Zhifu (Zhifu Island, Yantai, Shandong)', 'Climbs Zhifu again and leaves inscriptions', 'Undeterred by the attack, the emperor continued east and again climbed Zhifu, a headland jutting into the sea, where he set up two inscriptions praising his pacification of the world. He went on to Langya and returned to Xianyang by way of Shangdang. The stones are long lost, but their texts survive in the Records of the Grand Historian.'],
        { via: [[117.0, 36.65], [119.0, 36.7], [120.5, 37.35]], wiki: { zh: '芝罘岛', en: 'Zhifu Island' } }),
      w(-215, 119.6, 39.93,
        ['碣石（今河北秦皇岛一带）', '巡视碣石，刻《碣石门辞》', '第四次出巡，始皇帝北上到渤海边的碣石，派燕人卢生入海寻访仙人，又派韩终等人求不死之药，并在碣石门刻石。他还下令拆毁关东各国旧有的城郭、决通阻碍水流的堤防。今秦皇岛、绥中沿海发现有大型秦代行宫遗址。'],
        ['Jieshi (around Qinhuangdao, Hebei)', 'Visits Jieshi and has the Jieshi Gate inscription carved', 'On his fourth tour the emperor travelled north to Jieshi, sent the magician Lu Sheng to sea to seek immortals and others to find the elixir of life, and had an inscription cut at the Jieshi Gate. He also had old city walls and dykes pulled down. Large Qin palace sites have been excavated on the nearby coast.'],
        { via: [[120.7, 36.9], [119.85, 35.8], [113.1, 36.2], [108.86, 34.38], [114.5, 38.0], [116.4, 39.9]] }),
      w(-215, 109.8, 37.95,
        ['上郡（治所在今陕西榆林东南）', '巡视北边，命蒙恬北击匈奴', '始皇帝从碣石沿北部边境西行，由上郡返回咸阳。卢生献上“亡秦者胡也”的谶语，他随即命蒙恬率三十万大军北击匈奴，次年夺取河套，沿黄河设置县城，并把秦、赵、燕三国旧长城连接起来，西起临洮、东至辽东。'],
        ['Shang commandery (seat southeast of present Yulin, Shaanxi)', 'Tours the northern frontier; sends Meng Tian against the Xiongnu', "From Jieshi the emperor rode west along the frontier, returning through Shang commandery. Shown a prophecy that 'Hu will destroy Qin', he sent Meng Tian north with 300,000 men against the Xiongnu. The next year they took the Ordos, garrisoned the Yellow River and linked the old walls of Qin, Zhao and Yan into one line from Lintao to Liaodong."],
        { via: [[116.0, 40.3], [113.3, 40.1], [111.0, 39.3]], event: 'great-wall-qin' }),
      w(-213, 108.86, 34.38,
        ['咸阳', '下令焚书', '咸阳宫酒宴上，博士淳于越主张效法古制分封子弟。丞相李斯斥之为以古非今，建议除秦国史书和医药、卜筮、种树之书外，民间所藏《诗》《书》、百家语一律烧毁，始皇帝准奏。次年他迁怒于诽谤自己的方士，在咸阳坑杀四百六十余人。'],
        ['Xianyang', 'Orders the burning of the books', "At a palace banquet the scholar Chunyu Yue urged a return to ancient feudal practice. The chancellor Li Si denounced using the past to criticise the present and proposed burning private copies of the Odes, the Documents and the philosophers, sparing only Qin's annals and works on medicine, divination and farming. Next year some 460 scholars were executed at Xianyang."],
        { wiki: { zh: '焚书坑儒', en: 'Burning of books and burying of scholars' } }),
      w(-210, 120.58, 30.0,
        ['会稽（今浙江绍兴）', '最后一次出巡，祭大禹、立会稽刻石', '始皇帝带着少子胡亥、丞相李斯和中车府令赵高开始第五次出巡。他先到云梦遥祭舜帝，顺长江东下，过丹阳、钱唐，渡浙江登上会稽山祭祀大禹，立石颂德。相传少年项羽在人群中看到车驾，说了一句“彼可取而代也”。'],
        ['Kuaiji (now Shaoxing, Zhejiang)', 'Last tour: sacrifices to Yu the Great at Kuaiji', "The emperor set out on his fifth tour with his youngest son Huhai, the chancellor Li Si and Zhao Gao. He sailed down the Yangtze, crossed the Qiantang river and climbed Mount Kuaiji to sacrifice to Yu the Great and set up a stele. The young Xiang Yu, watching the procession, is said to have remarked: 'He could be replaced.'"],
        { via: [[112.2, 30.35], [118.5, 31.7], [120.15, 30.27]] }),
      w(-210, 115.13, 37.17,
        ['沙丘（今河北广宗）', '病逝于沙丘平台', '始皇帝从会稽沿海北上，到琅琊、之罘，亲自用连弩射杀了一条大鱼，西行至平原津时染病。七月，他在沙丘平台去世，终年四十九岁。赵高与李斯秘不发丧，篡改遗诏，赐死长子扶苏和蒙恬，改立胡亥为二世皇帝。'],
        ['Shaqiu (now Guangzong, Hebei)', 'Dies at the Shaqiu palace', 'From Kuaiji the emperor travelled up the coast to Langya and Zhifu, where he shot a great fish, then turned west and fell ill at the Pingyuan ford. He died at Shaqiu in the seventh month, aged forty-nine. Zhao Gao and Li Si concealed the death and forged an edict ordering the heir Fusu to kill himself, enthroning Huhai instead.'],
        { via: [[120.6, 31.3], [119.45, 32.2], [119.0, 34.3], [119.6, 35.55], [120.7, 36.9], [121.3, 37.45], [119.2, 36.8], [116.43, 37.17]] }),
      w(-210, 109.254, 34.381,
        ['骊山（今陕西西安临潼区）', '归葬骊山陵', '为掩人耳目，车队绕道井陉、九原，沿直道返回咸阳，途中用一车咸鱼遮掩尸臭。九月，始皇帝葬入修建了三十多年的骊山陵，《史记》说墓中“以水银为百川江河大海”。1974年，当地农民在陵东打井时发现了兵马俑坑。'],
        ['Mount Li (Lintong District, Xi\'an, Shaanxi)', 'Buried in the mausoleum at Mount Li', 'To hide the death the cortege detoured through Jingxing and Jiuyuan and down the Straight Road, with a cart of salted fish to mask the smell. In the ninth month the emperor was buried in the tomb begun more than thirty years earlier. In 1974 farmers digging a well to its east uncovered the pits of the Terracotta Army.'],
        { via: [[114.13, 38.03], [109.85, 40.6], [108.9, 35.6]], wiki: { zh: '秦始皇陵', en: 'Mausoleum of the First Qin Emperor' } }),
    ],
    wiki: { zh: '秦始皇', en: 'Qin Shi Huang' },
  },
  {
    id: 'hannibal',
    name: { zh: '汉尼拔', en: 'Hannibal' },
    birth: -247, death: -183,
    title: { zh: '迦太基统帅', en: 'Carthaginian general' },
    region: 'africa', sprite: 'horse',
    summary: {
      zh: '迦太基军事统帅，哈米尔卡·巴卡之子。九岁随父前往伊比利亚，二十六岁接掌兵权，在第二次布匿战争中率军翻越阿尔卑斯山远征意大利，在特雷比亚河、特拉西梅诺湖和坎尼连败罗马大军，坎尼会战被奉为战术经典。他转战意大利十五年而未能迫使罗马屈服，终在扎马被大西庇阿击败。晚年流亡东方，为免被交给罗马而服毒自尽（卒年另有前181年之说）。',
      en: "Carthaginian general, son of Hamilcar Barca. Taken to Iberia at nine and given command there at twenty-six, he opened the Second Punic War by marching across the Alps into Italy, where he defeated Roman armies at the Trebia, Lake Trasimene and Cannae; the encirclement at Cannae is still studied as a tactical masterpiece. He campaigned in Italy for fifteen years without breaking Rome's will and was finally beaten by Scipio Africanus at Zama. He ended his life as an exile in the East, taking poison rather than be handed over to Rome (his death is also dated to 181 BCE).",
    },
    route: [
      w(-247, 10.32, 36.85,
        ['迦太基（今突尼斯市郊）', '生于迦太基名将哈米尔卡·巴卡之家', '汉尼拔出生时第一次布匿战争已近尾声，父亲哈米尔卡正在西西里统兵作战。迦太基战败后割让西西里、支付巨额赔款，又遭雇佣兵叛乱。据波利比乌斯转述汉尼拔本人的回忆，九岁那年父亲带他到祭坛前发誓：永不与罗马为友。'],
        ['Carthage (near Tunis, Tunisia)', 'Born into the family of the general Hamilcar Barca', "Hannibal was born as the First Punic War neared its end, with his father Hamilcar commanding in Sicily. Defeat cost Carthage the island and a heavy indemnity, then a mercenary revolt. Polybius reports Hannibal's own recollection that when he was nine his father led him to an altar and made him swear never to be a friend to Rome."],
        { wiki: { zh: '迦太基', en: 'Carthage' } }),
      w(-237, -6.29, 36.53,
        ['加的斯（腓尼基人的加地尔，今西班牙加的斯）', '随父前往伊比利亚', '哈米尔卡率军来到伊比利亚半岛南端的腓尼基古城加地尔，着手为迦太基开辟新的领地。此后近二十年间，巴卡家族征服了半岛南部和东部，用当地的银矿和兵源重建国力，汉尼拔就在军营里长大成人。'],
        ['Gades (Phoenician Gadir, now Cadiz, Spain)', 'Goes to Iberia with his father', "Hamilcar took his army to the old Phoenician city of Gadir at the southern tip of Iberia and began carving out a new Carthaginian dominion. Over nearly twenty years the Barcids conquered the south and east of the peninsula, drawing on its silver mines and manpower to rebuild Carthage's strength, while Hannibal grew up in the camp."],
        { sea: true, via: [[5.0, 37.5], [-2.0, 36.3]] }),
      w(-221, -0.98, 37.6,
        ['新迦太基（今西班牙卡塔赫纳）', '接任伊比利亚迦太基军统帅', '父亲哈米尔卡在前229年前后的一次作战中身亡，继任的姐夫“美男子”哈斯德鲁巴建立了新迦太基城，并与罗马约定以埃布罗河为界。前221年哈斯德鲁巴遇刺，二十六岁的汉尼拔被全军推举为统帅，随后两年征服了半岛中部的部落。'],
        ['New Carthage (now Cartagena, Spain)', 'Takes command of the Carthaginian army in Iberia', 'Hamilcar died on campaign around 229 BCE and was succeeded by his son-in-law Hasdrubal the Fair, who founded New Carthage and agreed with Rome to keep south of the Ebro. When Hasdrubal was assassinated in 221 BCE the army acclaimed the twenty-six-year-old Hannibal as its general; he spent two years subduing the tribes of central Iberia.']),
      w(-219, -0.27, 39.68,
        ['萨贡托（今西班牙巴伦西亚以北）', '攻陷萨贡托，引发第二次布匿战争', '萨贡托位于埃布罗河以南，却与罗马结有盟约。汉尼拔围攻八个月后破城，本人在攻城时大腿中了一支标枪。罗马使团到迦太基要求交出汉尼拔，遭到拒绝，双方于前218年春宣战。'],
        ['Saguntum (now Sagunto, north of Valencia, Spain)', 'Takes Saguntum, setting off the Second Punic War', 'Saguntum lay south of the Ebro but was an ally of Rome. Hannibal took it after an eight-month siege in which he was wounded in the thigh by a javelin. Roman envoys went to Carthage to demand his surrender, were refused, and in the spring of 218 BCE the two powers were at war.'],
        { wiki: { zh: '萨贡托', en: 'Sagunto' } }),
      w(-218, 4.7, 44.0,
        ['罗讷河（今法国阿维尼翁以北）', '率步骑与战象渡过罗讷河', '汉尼拔从新迦太基出发，越过埃布罗河和比利牛斯山进入高卢，军中有三十七头战象。在罗讷河边，他派一支分队从上游偷渡包抄对岸的高卢人，用铺土的木筏把大象运过河，赶在罗马执政官西庇阿的军队到来前离开。'],
        ['Rhone river (north of Avignon, France)', 'Crosses the Rhone with infantry, cavalry and elephants', "Marching from New Carthage over the Ebro and the Pyrenees into Gaul, Hannibal reached the Rhone with an army that included 37 elephants. He sent a detachment upstream to take the hostile Gauls on the far bank from behind, ferried the elephants across on earth-covered rafts, and was gone before the consul Scipio's army arrived."],
        { via: [[0.6, 40.8], [2.86, 42.47], [3.0, 43.2], [4.3, 43.8]] }),
      w(-218, 6.9, 45.2,
        ['阿尔卑斯山（山口位置有争议）', '翻越阿尔卑斯山进入意大利', '时值深秋，大军用十五天翻越阿尔卑斯山，沿途遭山地部落伏击，山口已有积雪，人马和驮畜大量坠崖或冻饿而死。下到波河平原时，据波利比乌斯记载只剩两万步兵和六千骑兵。他究竟走的是哪个山口，至今仍无定论。'],
        ['The Alps (the pass is disputed)', 'Crosses the Alps into Italy', 'In late autumn the army took fifteen days to cross the Alps, ambushed by mountain tribes and struggling through fresh snow on the pass; men, horses and pack animals fell from the paths or died of cold and hunger. Polybius says only 20,000 infantry and 6,000 cavalry came down into the Po valley. Which pass Hannibal used is still debated.']),
      w(-218, 9.6, 45.0,
        ['特雷比亚河（今意大利皮亚琴察附近）', '大败罗马军', '汉尼拔先在提契诺河的骑兵战中击伤执政官西庇阿，波河流域的高卢人纷纷来投。十二月一个雨雪交加的清晨，他引诱另一位执政官森普罗尼乌斯的军队空腹涉过冰冷的特雷比亚河，由弟弟马戈率伏兵从背后杀出，罗马军大半被歼。'],
        ['Trebia river (near Piacenza, Italy)', 'Routs a Roman army', 'After wounding the consul Scipio in a cavalry fight on the Ticinus, Hannibal was joined by the Gauls of the Po valley. On a sleety December morning he lured the army of the other consul, Sempronius, across the icy Trebia before breakfast, then sprang an ambush under his brother Mago on its rear. Most of the Roman force was destroyed.'],
        { wiki: { zh: '特雷比亚河战役', en: 'Battle of the Trebia' } }),
      w(-217, 12.1, 43.18,
        ['特拉西梅诺湖（意大利中部）', '伏击歼灭罗马军', '汉尼拔穿越阿尔诺河沼泽南下，途中因眼疾一只眼睛失明。他把军队埋伏在特拉西梅诺湖北岸的山坡上，趁晨雾突袭沿湖行军的罗马军队，约一万五千人阵亡，执政官弗拉米尼乌斯战死。罗马随后任命费边为独裁官，改行拖延避战之策。'],
        ['Lake Trasimene (central Italy)', 'Destroys a Roman army in ambush', 'Hannibal marched south through the marshes of the Arno, losing the sight of one eye to an infection. He hid his army on the slopes north of the lake and fell on the Roman column in the morning mist; about 15,000 Romans died, the consul Flaminius among them. Rome appointed Fabius dictator, who adopted a strategy of delay.'],
        { wiki: { zh: '特拉西梅诺湖战役', en: 'Battle of Lake Trasimene' } }),
      w(-216, 16.13, 41.31,
        ['坎尼（意大利南部普利亚）', '两翼合围，歼灭罗马主力', '罗马集结约八万人的大军，由两位执政官率领决战。汉尼拔以约五万人迎战，让中央步兵且战且退，两翼的非洲步兵和骑兵随即合围，一天之内歼灭罗马军约五万人（一说七万）。相传骑兵将领马哈巴尔叹道：汉尼拔懂得取胜，却不懂得利用胜利。'],
        ['Cannae (Apulia, southern Italy)', 'Encircles and destroys the main Roman army', 'Rome fielded an unprecedented army of about 80,000 under both consuls. Hannibal, with some 50,000, let his centre give ground while African infantry and cavalry closed in from the wings; nearly 50,000 Romans, according to Livy, died in a day. His officer Maharbal reputedly said that he knew how to win a victory but not how to use one.'],
        { via: [[13.4, 42.9], [14.1, 42.3], [15.3, 41.6]], event: 'battle-of-cannae' }),
      w(-216, 14.25, 41.08,
        ['卡普阿（今意大利圣玛丽亚卡普阿韦泰雷）', '卡普阿倒戈，在此过冬', '坎尼之后，意大利南部许多城邦背离罗马，其中最重要的是坎帕尼亚的富庶大城卡普阿。汉尼拔率军入城过冬，罗马史家李维说军队从此被安逸生活消磨了斗志。罗马拒绝议和，重新组建军团，战争转入漫长的消耗。'],
        ['Capua (now Santa Maria Capua Vetere, Italy)', 'Wins over Capua and winters there', "After Cannae many communities of southern Italy went over to Hannibal, above all Capua, the rich chief city of Campania, where he took up winter quarters. The Roman historian Livy claimed that its comforts sapped the army's fighting spirit. Rome refused to negotiate, raised new legions, and the war settled into a long contest of attrition."]),
      w(-212, 17.23, 40.47,
        ['他林敦（今意大利塔兰托）', '里应外合夺取他林敦', '在城内亲迦太基贵族的接应下，汉尼拔趁夜进入南意大利最大的希腊城市他林敦，但罗马守军仍据守卫城，控制着港口入口。同一时期罗马人围攻叙拉古和卡普阿，前209年费边又收复他林敦，汉尼拔的活动范围日渐缩小。'],
        ['Tarentum (now Taranto, Italy)', 'Seizes Tarentum by treachery', "Helped by sympathisers inside, Hannibal slipped by night into Tarentum, the largest Greek city of southern Italy, though a Roman garrison held out in the citadel commanding the harbour mouth. Meanwhile Rome was besieging Syracuse and Capua, and in 209 BCE Fabius retook Tarentum. Hannibal's room for manoeuvre steadily shrank."]),
      w(-211, 12.52, 41.93,
        ['罗马城下', '兵临罗马城下', '为解卡普阿之围，汉尼拔突然率军北上，在距罗马城数公里的阿尼奥河边扎营，并带骑兵驰近科利纳门窥探城防，“汉尼拔到了城门口”从此成为罗马人的口头禅。罗马不为所动，围城部队也未撤回，他只得退兵，卡普阿随即陷落。'],
        ['Before the walls of Rome', 'Marches to the gates of Rome', "To draw the Romans off besieged Capua, Hannibal made a sudden dash north, camped by the river Anio a few kilometres from Rome and rode up to the Colline Gate to view the walls. 'Hannibal at the gates' became a Roman byword. But the city held firm, the siege went on, he withdrew, and Capua fell soon afterwards."]),
      w(-205, 17.12, 39.08,
        ['克罗顿（今意大利克罗托内）', '困守意大利“靴尖”', '前207年，率援军翻越阿尔卑斯山的弟弟哈斯德鲁巴在梅陶罗河战死，头颅被抛入汉尼拔营中。此后他退守布鲁提乌姆山地，以克罗顿为基地。离开意大利前，他在附近的赫拉神庙立下布匿文和希腊文铭刻记述战功，波利比乌斯曾亲眼见过。'],
        ['Croton (now Crotone, Italy)', 'Hemmed in at the toe of Italy', "In 207 BCE his brother Hasdrubal, bringing reinforcements over the Alps, was killed at the Metaurus and his head thrown into Hannibal's camp. Hannibal fell back on Bruttium, with Croton as his base. Before leaving Italy he set up an inscription in Punic and Greek at the nearby temple of Hera Lacinia recording his deeds, which Polybius later read."],
        { via: [[14.25, 41.08], [15.8, 40.63], [16.25, 39.3]] }),
      w(-203, 10.64, 35.83,
        ['哈德鲁梅图姆（今突尼斯苏塞）', '奉召回国', '大西庇阿率罗马军登陆非洲，联合努米底亚的马西尼萨连败迦太基军，迦太基元老院急召汉尼拔回国。他带着追随多年的老兵从克罗顿启航，在小莱普提斯登陆后驻扎哈德鲁梅图姆，这是他离开三十四年后第一次回到非洲。'],
        ['Hadrumetum (now Sousse, Tunisia)', 'Recalled to Africa', "Scipio had landed in Africa and, with the Numidian prince Masinissa, beaten Carthage's armies, and the Carthaginian senate summoned Hannibal home. He sailed from Croton with his veterans, landed at Leptis Minor and made his base at Hadrumetum. It was his first return to Africa since leaving as a boy thirty-four years earlier."],
        { sea: true, via: [[17.5, 39.0], [12.0, 37.0]] }),
      w(-202, 9.45, 36.3,
        ['扎马（今突尼斯西北部，具体位置有争议）', '被大西庇阿击败', '决战前汉尼拔与西庇阿曾当面会谈，未能达成和议。战斗中罗马军队让出通道放过迦太基的八十头战象，马西尼萨的努米底亚骑兵击溃敌骑后回师夹击，汉尼拔的老兵方阵终被击溃。迦太基被迫求和，交出舰队、放弃海外领地并赔款一万塔兰特。'],
        ['Zama (north-western Tunisia; exact site disputed)', 'Defeated by Scipio Africanus', "Hannibal and Scipio met face to face before the battle but could not agree terms. The Roman maniples opened lanes to let Carthage's eighty elephants pass through, and Masinissa's Numidian cavalry, having driven off the enemy horse, returned to strike Hannibal's veterans in the rear. Carthage sued for peace, giving up its fleet and overseas possessions and paying 10,000 talents."],
        { wiki: { zh: '扎马战役', en: 'Battle of Zama' } }),
      w(-196, 10.32, 36.85,
        ['迦太基', '出任最高行政长官，整顿财政', '战后汉尼拔当选为迦太基最高行政长官“苏菲特”。他改革法官会议的任期，清查被贵族侵吞的公款，使迦太基不必加税就能偿付对罗马的赔款，因此得罪了寡头集团。政敌向罗马告发他与塞琉古国王安条克三世暗通款曲。'],
        ['Carthage', 'Elected suffete and reforms the finances', 'After the war Hannibal was elected suffete, chief magistrate of Carthage. He limited the tenure of the powerful board of judges and exposed the embezzlement of public funds, showing that the indemnity to Rome could be paid without new taxes. The oligarchs he had offended denounced him to Rome for intriguing with the Seleucid king Antiochus III.']),
      w(-195, 35.2, 33.27,
        ['推罗（今黎巴嫩苏尔）', '被迫流亡，投奔塞琉古王国', '罗马使团抵达迦太基后，汉尼拔连夜骑马逃到海边自家的庄园，登船经克肯纳群岛驶往迦太基的母邦推罗，受到热情接待。迦太基当局随后没收他的财产、拆毁他的住宅，他从此再未回到故乡。'],
        ['Tyre (now Sur, Lebanon)', 'Flees into exile in the Seleucid kingdom', 'When a Roman embassy arrived in Carthage, Hannibal rode through the night to his estate on the coast, took ship by way of the Kerkennah islands and sailed to Tyre, mother city of Carthage, where he was warmly received. The Carthaginian authorities confiscated his property and demolished his house; he never saw his homeland again.'],
        { sea: true, via: [[12.0, 35.0], [25.0, 34.0]] }),
      w(-195, 27.34, 37.94,
        ['以弗所（今土耳其塞尔丘克）', '在以弗所谒见安条克三世', '汉尼拔经安条克城赶到以弗所，见到正准备与罗马开战的安条克三世，建议由自己率军再攻意大利，未被采纳。战争中他只受命在腓尼基组建一支舰队，前190年在西代附近被罗得岛海军击败。相传西庇阿曾在以弗所与他谈论谁是最伟大的将领。'],
        ['Ephesus (now Selcuk, Turkey)', 'Joins Antiochus III at Ephesus', 'Coming by way of Antioch, Hannibal met Antiochus III at Ephesus on the eve of war with Rome and urged an invasion of Italy under his command, in vain. He was given only a Phoenician fleet, which the Rhodians defeated off Side in 190 BCE. An anecdote has Scipio meeting him here to debate who was the greatest general.'],
        { via: [[36.0, 34.0], [36.16, 36.2], [34.9, 36.92], [32.5, 37.87], [30.17, 38.07]] }),
      w(-188, 24.95, 35.06,
        ['戈尔廷（克里特岛）', '安条克战败，避往克里特', '安条克三世在马格尼西亚战败，罗马在和约中要求交出汉尼拔，他抢先逃到克里特岛的戈尔廷。据奈波斯记载，为防当地人觊觎他的钱财，他把灌了铅的陶罐寄存在神庙里，真正的黄金则藏在自家院中的铜像内。'],
        ['Gortyn (Crete)', 'Flees to Crete after the defeat of Antiochus', "After Antiochus III was beaten at Magnesia, the Romans demanded Hannibal's surrender as a term of peace, and he escaped to Gortyn in Crete. Cornelius Nepos tells how, to protect his fortune from the Cretans, he deposited jars filled with lead in a temple while keeping his gold hidden inside hollow bronze statues in his courtyard."],
        { sea: true, via: [[26.9, 37.92], [26.45, 37.62], [26.3, 37.15], [25.98, 36.55], [26.55, 35.65], [26.65, 35.05], [26.1, 34.72], [25.1, 34.8]] }),
      w(-183, 29.43, 40.8,
        ['利比萨（今土耳其盖布泽）', '为免被引渡给罗马，服毒自尽', '汉尼拔最后投奔比提尼亚国王普鲁西亚斯一世，帮他与罗马的盟友帕加马作战，相传曾把装满毒蛇的陶罐抛上敌舰取胜。罗马使节弗拉米尼努斯前来索人，士兵包围了他在利比萨的住处，他服下随身携带的毒药，终年约六十四岁。'],
        ['Libyssa (now Gebze, Turkey)', 'Takes poison to avoid being handed over to Rome', "Hannibal's last refuge was the court of Prusias I of Bithynia, whom he helped against Rome's ally Pergamon, reputedly winning a sea fight by hurling jars of snakes onto the enemy ships. When the Roman envoy Flamininus came to demand him and soldiers surrounded his house at Libyssa, he swallowed the poison he carried with him. He was about sixty-four."],
        { sea: true, via: [[25.1, 34.8], [26.1, 34.72], [26.65, 35.05], [26.55, 35.65], [25.98, 36.55], [26.3, 37.15], [26.45, 37.62], [25.75, 38.3], [25.7, 39.0], [25.75, 39.75], [26.1, 40.03], [26.33, 40.1], [26.46, 40.22], [26.65, 40.37], [26.9, 40.47], [27.6, 40.8], [28.6, 40.8], [29.3, 40.72]] }),
    ],
    wiki: { zh: '汉尼拔', en: 'Hannibal' },
  },
  {
    id: 'zhang-qian',
    name: { zh: '张骞', en: 'Zhang Qian' },
    birth: -175, death: -114, approx: true,
    title: { zh: '外交家、探险家', en: 'Diplomat and explorer' },
    region: 'china', lineage: 'china', sprite: 'camel',
    summary: {
      zh: '西汉外交家、探险家，汉中城固人，生年不详（一说约前175年）。前139年或前138年受汉武帝派遣出使大月氏，途中两次被匈奴扣押，历十三年方回；后又出使乌孙。他带回的西域诸国情报，促成了汉朝经营西域以及中国与中亚、西亚之间的官方往来，司马迁称之为“凿空”，后世誉他为丝绸之路的开拓者。',
      en: "Diplomat and explorer of the Western Han, from Chenggu in Hanzhong; his birth year is unknown (c. 175 BCE by one estimate). In 139 or 138 BCE Emperor Wu sent him to seek an alliance with the Yuezhi against the Xiongnu. Twice captured by the Xiongnu, he returned only after thirteen years, and later led a second embassy to the Wusun. The knowledge he brought back of the lands and peoples of Central Asia opened official contact between China and the West, a feat the historian Sima Qian called 'piercing the void', and he is remembered as the pioneer of the Silk Road.",
    },
    route: [
      w(-175, 107.33, 33.15,
        ['城固（汉中郡，今陕西城固）', '生于汉中城固', '张骞是汉中郡城固人，生年和早年经历史书没有记载，这里的年份只是约数。《史记》说他“为人强力，宽大信人”，体魄强健、待人宽厚，很得边地各族的信任。汉武帝建元年间，他在朝廷担任郎官。'],
        ['Chenggu (Hanzhong commandery, now Chenggu, Shaanxi)', 'Born at Chenggu in Hanzhong', 'Zhang Qian came from Chenggu in Hanzhong; neither his birth year nor his early life is recorded, and the date given here is only an estimate. Sima Qian describes him as physically strong, generous and trusting, a man whom foreign peoples liked. Early in the reign of Emperor Wu he was serving as a gentleman of the palace.']),
      w(-138, 108.94, 34.34,
        ['长安（今陕西西安）', '奉命率百余人出使大月氏', '汉武帝从匈奴降人口中得知，被匈奴击败西迁的大月氏怀恨在心，却无人与之联手，于是招募使者前往联络，共同夹击匈奴。郎官张骞应募，带着匈奴人向导堂邑父等一百多人从长安出发，这是中原王朝第一次派使团深入西域。'],
        ["Chang'an (now Xi'an, Shaanxi)", 'Sets out with over a hundred men for the Yuezhi', "Emperor Wu learned from Xiongnu captives that the Yuezhi, driven west by the Xiongnu, nursed a grudge but had no ally, and called for envoys to propose a joint attack. Zhang Qian volunteered and left Chang'an with more than a hundred men, including the Xiongnu-born guide Tangyi Fu. It was the first Chinese embassy sent deep into Central Asia."],
        { event: 'zhang-qian-mission' }),
      w(-138, 103.86, 35.38,
        ['陇西（郡治狄道，今甘肃临洮）', '出陇西，途中被匈奴俘获', '使团从汉朝西部边郡陇西出塞。当时河西走廊还在匈奴控制之下，一行人不久就被匈奴骑兵截获，押送单于王庭。军臣单于质问：月氏在我北方，汉朝怎能派使者过去？我若派人出使南越，汉朝肯放行吗？'],
        ['Longxi (seat at Didao, now Lintao, Gansu)', 'Leaves through Longxi and is captured by the Xiongnu', "The mission left Han territory through the frontier commandery of Longxi. The Hexi Corridor beyond was then in Xiongnu hands, and the party was soon intercepted and taken to the court of the chanyu. 'The Yuezhi lie to my north,' he told them. 'If I wished to send envoys to Yue, would Han let them through?'"]),
      w(-137, 104.5, 46.5,
        ['匈奴单于庭（漠北，位置为示意）', '被扣留十余年，娶妻生子', '匈奴扣留张骞十余年，还给他娶了匈奴妻子，生有儿子。但他始终保留着象征使命的汉节，没有忘记自己的任务。看管渐渐放松后，他抓住机会带着随从向西逃走。'],
        ['Court of the Xiongnu chanyu (Mongolian steppe; location indicative)', 'Held for more than ten years; takes a wife', 'The Xiongnu detained Zhang Qian for over ten years and gave him a wife, with whom he had a son. Through it all he kept the staff that marked him as an imperial envoy and did not forget his mission. When the watch on him grew lax, he seized the chance to escape westward with his companions.'],
        { wiki: { zh: '匈奴', en: 'Xiongnu' } }),
      w(-129, 71.78, 40.77,
        ['大宛（今费尔干纳盆地）', '逃脱西行至大宛', '张骞一行向西奔走数十日，靠堂邑父射猎禽兽充饥，终于到达大宛。大宛王早闻汉朝富饶，欣然派向导和翻译护送他们前往康居。张骞在这里见到良马和葡萄酒、苜蓿，后来一一向汉武帝报告。'],
        ['Dayuan (the Fergana valley)', 'Escapes west to Dayuan', "The fugitives travelled west for weeks, living on game shot by Tangyi Fu, until they reached Dayuan. Its king had heard of Han's wealth and gladly provided guides and interpreters to take them on to Kangju. Here Zhang Qian saw the fine horses, grape wine and alfalfa that he later described to Emperor Wu."],
        { wiki: { zh: '大宛', en: 'Dayuan' } }),
      w(-129, 68.3, 42.4,
        ['康居（今锡尔河中游一带）', '经康居南下', '康居是锡尔河中游一带的游牧国家，张骞说它“与月氏大同俗”，国小而夹在大国之间，南边服事月氏，东边服事匈奴。康居人把汉使一路转送到大月氏。'],
        ['Kangju (middle Syr Darya region)', 'Travels south through Kangju', 'Kangju was a nomadic state along the middle Syr Darya. Zhang Qian reported that its customs resembled those of the Yuezhi and that, small and caught between powers, it deferred to the Yuezhi in the south and the Xiongnu in the east. The people of Kangju passed the envoys on to the Great Yuezhi.']),
      w(-128, 67.3, 37.3,
        ['大月氏（阿姆河北岸）', '抵达大月氏，月氏已无意东归', '大月氏此时已征服阿姆河以南的大夏，占有肥沃安宁的土地，又觉得汉朝太远，早已没有向匈奴复仇的念头。张骞在此停留一年多，始终“不得月氏要领”，结盟的使命落空，却得以实地了解中亚各国的情形。'],
        ['Great Yuezhi (north bank of the Amu Darya)', 'Reaches the Yuezhi, who have no wish to return east', 'The Great Yuezhi had by now subdued Daxia south of the Amu Darya and were living securely on rich land; Han seemed far away and they had lost all thought of revenge on the Xiongnu. Zhang Qian stayed over a year without getting a clear answer. The alliance came to nothing, but he had seen Central Asia at first hand.'],
        { wiki: { zh: '月氏', en: 'Yuezhi' } }),
      w(-128, 66.9, 36.76,
        ['大夏（巴克特里亚，今阿富汗北部巴尔赫一带）', '考察大夏，见到邛竹杖与蜀布', '张骞渡过阿姆河来到大夏，这里城郭林立、商贾云集，却兵弱畏战。他在市场上看到产自蜀地的邛竹杖和蜀布，当地人说是从东南数千里外的身毒（印度）贩来的。他由此推断，从蜀地西南必有一条通往身毒的道路。'],
        ['Daxia (Bactria, around Balkh in northern Afghanistan)', 'Visits Daxia and finds bamboo and cloth from Shu', 'Crossing the Amu Darya into Daxia, Zhang Qian found a land of walled towns and busy markets but weak in war. In the bazaar he saw bamboo canes and cloth from Shu (Sichuan), said to come by way of Shendu (India), several thousand li to the south-east. He inferred that a route must lead from south-west China to India.'],
        { wiki: { zh: '巴克特里亚', en: 'Bactria' } }),
      w(-127, 96.0, 36.5,
        ['羌中（今青海柴达木盆地一带，位置为示意）', '沿昆仑山北麓东归，再被匈奴所获', '为避开匈奴，张骞回程改走塔里木盆地南缘，沿昆仑山、阿尔金山北麓东行，打算穿过羌人地区回国，不料仍被匈奴抓获，又被扣留一年多。途中他记下了于阗、楼兰等绿洲城邦和盐泽（罗布泊）的情况。'],
        ['Qiang country (around the Qaidam basin, Qinghai; location indicative)', 'Returns along the southern mountains and is captured again', 'Avoiding the Xiongnu, Zhang Qian went home along the southern rim of the Tarim basin, skirting the Kunlun and Altun mountains, meaning to cross the land of the Qiang. The Xiongnu caught him all the same and held him over a year. On the way he noted the oases of Khotan and Loulan and the salt lake of Lop Nor.'],
        { via: [[73.0, 37.6], [77.25, 38.42], [79.93, 37.11], [85.53, 38.14], [88.17, 39.02]] }),
      w(-126, 108.94, 34.34,
        ['长安', '趁匈奴内乱逃归，百余人仅二人生还', '军臣单于去世，匈奴贵族争位内乱，张骞带着匈奴妻子和堂邑父乘机逃回长安。出发时的一百多人，十三年后只有他们二人生还。他向汉武帝详细报告了大宛、大月氏、大夏、康居以及传闻中的安息、条支、身毒等国的情况，被拜为太中大夫。'],
        ["Chang'an", 'Escapes home; only two of the hundred return', "When the chanyu died and the Xiongnu fought over the succession, Zhang Qian escaped with his Xiongnu wife and Tangyi Fu to Chang'an. Of more than a hundred who set out thirteen years before, only these two returned. His report to Emperor Wu described Dayuan, the Yuezhi, Daxia and Kangju, and what he had heard of Parthia and India."]),
      w(-123, 111.8, 40.4,
        ['定襄（今内蒙古和林格尔一带）', '随卫青出击匈奴，封博望侯', '张骞以校尉身份随大将军卫青从定襄出塞。他在匈奴生活多年，熟悉草原上水草所在，大军因而不致困乏。凭借此功和出使西域的劳绩，他被封为博望侯；后来汉朝派往西域的使者多自称博望侯，以取信于各国。'],
        ['Dingxiang (around Horinger, Inner Mongolia)', 'Campaigns against the Xiongnu; made Marquis of Bowang', 'Zhang Qian served as a colonel when the general Wei Qing marched from Dingxiang against the Xiongnu. His years on the steppe had taught him where water and pasture lay, and the army did not go short. For this and his embassy he was created Marquis of Bowang, a title later envoys invoked to win trust in the west.']),
      w(-122, 104.07, 30.66,
        ['蜀郡、犍为（今四川成都、宜宾一带）', '主持探寻通往身毒的西南道', '按照张骞的建议，汉武帝命他在蜀郡和犍为郡组织使者，分四路向西南探寻经身毒通往大夏的道路。各路使者走出一两千里后，分别被氐、筰和昆明等部族阻拦，未能打通，但汉朝由此重新开始经营西南夷地区。'],
        ['Shu and Qianwei commanderies (around Chengdu and Yibin, Sichuan)', 'Directs the search for a south-western route to India', "On Zhang Qian's advice, Emperor Wu had him dispatch envoys from Shu and Qianwei by four routes to find a way through the south-west to Shendu (India) and Daxia. Each party was stopped after one or two thousand li by local peoples such as the Kunming. The road was not opened, but Han turned again to the south-western frontier."],
        { via: [[108.94, 34.34]] }),
      w(-121, 119.0, 41.5,
        ['右北平（今内蒙古宁城一带）', '与李广出塞，失期当斩', '张骞以卫尉身份与“飞将军”李广分兵从右北平出击匈奴。李广率四千骑兵被左贤王数万人包围，苦战两日、几乎全军覆没，张骞率领的主力迟到一步才将匈奴逼退。按军法他延误军期当处斩，出钱赎罪后被贬为平民。'],
        ['Youbeiping (around Ningcheng, Inner Mongolia)', 'Arrives late to support Li Guang and loses his rank', "As commandant of the guards, Zhang Qian marched from Youbeiping against the Xiongnu in concert with the general Li Guang. Li's 4,000 horsemen were surrounded by a far larger force and almost wiped out before Zhang Qian's main body came up, too late. Condemned to death for missing the rendezvous, he paid a fine instead and was reduced to commoner."],
        { via: [[108.94, 34.34]] }),
      w(-119, 78.4, 42.5,
        ['乌孙（都城赤谷城，今伊塞克湖东南）', '第二次出使西域，至乌孙', '匈奴被逐出河西后，张骞建议联络乌孙东迁故地，以“断匈奴右臂”。他以中郎将率三百人，带着数以万计的牛羊和金帛再度西行。年老的乌孙王不敢得罪匈奴，没有答应东迁，张骞便分遣副使前往大宛、康居、大月氏、大夏、安息、身毒等国。'],
        ['Wusun (capital Chigu, south-east of Lake Issyk-Kul)', 'Second mission to the Western Regions: the Wusun', "With the Xiongnu driven from the Hexi Corridor, Zhang Qian proposed inviting the Wusun back east to 'cut off the right arm' of the Xiongnu. He set out with 300 men, great herds and rich gifts. The aged Wusun king would not commit himself, so Zhang Qian sent deputy envoys on to Dayuan, Kangju, the Yuezhi, Daxia, Parthia and India."],
        { via: [[108.94, 34.34], [103.7, 36.1], [98.5, 39.75], [94.66, 40.14], [86.57, 41.73], [80.27, 41.17]], wiki: { zh: '乌孙', en: 'Wusun' } }),
      w(-115, 108.94, 34.34,
        ['长安', '偕乌孙使者归汉，拜为大行', '乌孙派出数十名使者、带着数十匹良马随张骞来到长安，亲眼见到汉朝的富庶，乌孙从此逐渐倒向汉朝，后来还与汉室和亲。张骞被任命为主管对外交往的大行，位列九卿。'],
        ["Chang'an", 'Returns with Wusun envoys; appointed Grand Messenger', "Dozens of Wusun envoys came back to Chang'an with Zhang Qian, bringing dozens of fine horses, and saw the size and wealth of Han for themselves; the Wusun drew steadily closer to Han and later sealed the tie by marriage. Zhang Qian was appointed Grand Messenger, the minister in charge of relations with foreign peoples."],
        { via: [[80.27, 41.17], [86.57, 41.73], [94.66, 40.14], [98.5, 39.75], [103.7, 36.1]] }),
      w(-114, 108.94, 34.34,
        ['长安', '卒，葬于故乡汉中城固', '张骞回国一年多后去世，归葬故乡城固。此后他派往各国的副使陆续带着当地使者回到长安，“西北国始通于汉”，使者和商队往来不绝。城固的张骞墓2014年作为“丝绸之路：长安—天山廊道的路网”的一部分列入世界遗产名录。'],
        ["Chang'an", 'Dies and is buried at Chenggu', "Zhang Qian died a little over a year after his return and was buried in his native Chenggu. The deputies he had sent onward returned with envoys from the western states, and missions and caravans were soon travelling in both directions. In 2014 his tomb was inscribed on the World Heritage List as part of the Silk Roads: Chang'an-Tianshan Corridor."]),
    ],
    wiki: { zh: '张骞', en: 'Zhang Qian' },
  },
  {
    id: 'caesar',
    name: { zh: '尤利乌斯·凯撒', en: 'Julius Caesar' },
    birth: -100, death: -44,
    title: { zh: '罗马政治家、军事家', en: 'Roman statesman and general' },
    region: 'europe', lineage: 'rome', sprite: 'horse',
    summary: {
      zh: '古罗马政治家、军事家、作家。出身古老的尤利乌斯氏族，前60年与庞培、克拉苏结成“前三头同盟”，随后用八年征服高卢，两度渡海进军不列颠，并留下《高卢战记》。前49年率军渡过卢比孔河发动内战，击败庞培后成为终身独裁官，推行儒略历等改革。前44年3月15日遇刺身亡，其养子屋大维后来建立了罗马帝国。',
      en: 'Roman statesman, general and author, born into the ancient patrician clan of the Julii. In 60 BCE he formed the so-called First Triumvirate with Pompey and Crassus, then spent eight years conquering Gaul, twice crossing to Britain, and described the campaigns in his Commentaries on the Gallic War. In 49 BCE he led his army across the Rubicon and began a civil war; having defeated Pompey he became dictator for life and carried through reforms including the Julian calendar. He was assassinated on 15 March 44 BCE, and his adopted son Octavian went on to found the Roman Empire.',
    },
    route: [
      w(-100, 12.4823, 41.8933,
        ['罗马', '生于古老的尤利乌斯家族', '凯撒出生于罗马城的平民区苏布拉。尤利乌斯氏族自称是女神维纳斯之子埃涅阿斯的后裔，门第古老却久不显赫；他的姑父是平民派领袖马略。苏拉掌权后，十八岁的凯撒因拒绝与秦纳之女离婚而被剥夺家产，一度逃亡在外。'],
        ['Rome', 'Born into the ancient Julian clan', 'Caesar was born in the Subura, a crowded quarter of Rome. The Julii claimed descent from Aeneas, son of Venus, but had long been out of the front rank; his aunt was married to the popular leader Marius. When Sulla took power, the eighteen-year-old Caesar refused to divorce the daughter of Cinna, lost his inheritance and went into hiding.']),
      w(-81, 26.55, 39.11,
        ['米蒂利尼（莱斯沃斯岛）', '东方从军，获“公民冠”', '为避开苏拉，凯撒到亚细亚行省总督麾下任职，曾奉命前往比提尼亚国王尼科美德的宫廷调集舰队。在攻打米蒂利尼的战斗中，他因救下一名罗马公民的性命而获得橡叶编成的“公民冠”，这是罗马军人极高的荣誉。'],
        ['Mytilene (island of Lesbos)', 'Serves in the East and wins the civic crown', 'To keep clear of Sulla, Caesar joined the staff of the governor of Asia, who sent him to the court of King Nicomedes of Bithynia to fetch a fleet. At the storming of Mytilene he saved the life of a fellow citizen and was awarded the civic crown of oak leaves, one of the highest Roman military honours.'],
        { sea: true, via: [[12.2, 41.65], [13.9, 40.3], [15.4, 38.6], [15.68, 38.3], [15.6, 38.2], [15.62, 37.95], [16.3, 37.6], [21.3, 36.3], [23.0, 35.95], [25.3, 36.2], [25.98, 36.55], [26.3, 37.15], [26.45, 37.62], [25.8, 38.1], [25.75, 38.75], [26.1, 38.85], [26.62, 38.97]] }),
      w(-75, 27.08, 37.29,
        ['法马库萨岛（今希腊法尔马科尼西岛）', '被海盗劫持', '凯撒前往罗得岛求学途中，在法马库萨岛附近被奇里乞亚海盗俘获，扣押近四十天。据普鲁塔克记载，海盗索要二十塔兰特赎金，他嫌少，自行加到五十，还笑言日后要把他们全都钉上十字架。获释后他果然集结船只抓获海盗，一一处死。'],
        ['Pharmacusa (now Farmakonisi, Greece)', 'Captured by pirates', 'Sailing to Rhodes to study rhetoric, Caesar was seized by Cilician pirates off Pharmacusa, south of Miletus, and held for nearly forty days. Plutarch says that when they asked a ransom of twenty talents he insisted he was worth fifty, and joked that he would crucify them all. Once freed he raised ships, captured them and did so.'],
        { sea: true, via: [[26.62, 38.97], [26.1, 38.85], [25.75, 38.75], [25.8, 38.1], [26.45, 37.62], [26.8, 37.4]] }),
      w(-63, 12.4823, 41.8933,
        ['罗马', '当选大祭司长', '回到罗马后，凯撒靠慷慨举债收买人心，步步晋升。前63年，三十七岁的他击败两位资深元老，当选终身任职的大祭司长。同年在元老院辩论如何处置喀提林阴谋的同党时，他力主监禁而非处死，与小加图针锋相对。'],
        ['Rome', 'Elected pontifex maximus', 'Back in Rome, Caesar climbed the ladder of office on borrowed money and lavish generosity. In 63 BCE, aged thirty-seven, he defeated two senior senators to become pontifex maximus, head of the state religion for life. In the Senate debate on the Catilinarian conspirators that year he argued for imprisonment rather than execution, against Cato the Younger.'],
        { sea: true, via: [[26.6, 37.05], [25.98, 36.55], [25.3, 36.2], [23.0, 35.95], [21.3, 36.3], [16.3, 37.6], [15.62, 37.95], [15.6, 38.2], [15.68, 38.3], [15.4, 38.6], [13.9, 40.3], [12.2, 41.65]] }),
      w(-61, -6.29, 36.53,
        ['加的斯（罗马远西班牙行省）', '出任远西班牙总督，初掌兵权', '卸任裁判官后，凯撒出任远西班牙总督。他率军征讨卢西塔尼亚的山地部落，又派船沿大西洋海岸北上直抵今拉科鲁尼亚，所获战利品足以还清巨额债务。相传他早年在此地的赫拉克勒斯神庙见到亚历山大像，曾叹息自己年过三十仍一事无成。'],
        ['Gades (now Cadiz, in Roman Further Spain)', 'Governs Further Spain: his first army command', 'After his praetorship Caesar governed Further Spain. He campaigned against the hill peoples of Lusitania and sent a fleet from Gades up the Atlantic coast as far as Brigantium (A Coruna), winning enough booty to pay off his enormous debts. An earlier visit to Gades is the setting for the story of his sighing before a statue of Alexander.'],
        { via: [[10.4, 43.72], [8.93, 44.41], [7.3, 43.72], [4.36, 43.84], [3.0, 43.2], [2.9, 42.45], [1.9, 41.75], [0.5, 40.85], [-0.45, 39.5], [-3.8, 37.9]] }),
      w(-59, 12.4823, 41.8933,
        ['罗马', '结成“前三头同盟”，出任执政官', '凯撒放弃凯旋式回罗马竞选，并促成宿敌庞培与克拉苏和解，三人私下结盟，史称“前三头同盟”；他还把女儿尤利娅嫁给庞培。前59年他出任执政官，不顾同僚和元老院反对强行通过土地法，并为自己取得山南高卢等行省为期五年的总督职位。'],
        ['Rome', 'Forms the First Triumvirate and serves as consul', 'Caesar gave up a triumph to stand for the consulship and reconciled the rivals Pompey and Crassus; their private pact is known as the First Triumvirate, and he married his daughter Julia to Pompey. As consul in 59 BCE he forced through a land law against his colleague Bibulus and secured a five-year command in Gaul and Illyricum.'],
        { via: [[-3.8, 37.9], [-0.45, 39.5], [0.5, 40.85], [1.9, 41.75], [2.9, 42.45], [3.0, 43.2], [4.36, 43.84], [7.3, 43.72], [8.93, 44.41], [10.4, 43.72]] }),
      w(-58, 4.03, 46.92,
        ['比布拉克特（今法国欧坦附近的伯夫雷山）', '出任高卢总督，开始高卢战争', '赫尔维蒂人举族西迁，凯撒以保护罗马盟友埃杜伊人为由出兵，在比布拉克特附近将其击败，迫使幸存者返回故地。同年他又在阿尔萨斯击溃渡过莱茵河的日耳曼首领阿里奥维斯图斯。此后八年，他逐步征服了整个高卢。'],
        ['Bibracte (Mont Beuvray, near Autun, France)', 'Takes up his command and opens the Gallic War', "When the Helvetii set out to migrate west, Caesar intervened in the name of Rome's allies the Aedui, defeated them near Bibracte and sent the survivors home. Later that year he routed the German leader Ariovistus, who had crossed the Rhine, in Alsace. Over the following eight years he brought the whole of Gaul under Roman control."],
        { via: [[11.3, 43.8], [9.7, 45.05], [7.7, 45.07], [6.15, 46.2], [4.85, 46.3]], wiki: { zh: '高卢战争', en: 'Gallic Wars' } }),
      w(-55, 7.47, 50.43,
        ['莱茵河（今德国科布伦茨、新维德一带）', '十天架桥，渡过莱茵河', '为震慑不断渡河侵扰的日耳曼人，凯撒命工兵在水深流急的莱茵河上打下木桩，十天内架起一座数百米长的木桥。大军过河后在对岸巡行十八天，焚毁苏刚布里人的村庄，然后撤回高卢并拆毁桥梁。他是第一个率军越过莱茵河的罗马将领。'],
        ['Rhine (around Koblenz and Neuwied, Germany)', 'Bridges the Rhine in ten days', 'To overawe the Germans who kept raiding across the river, Caesar had his engineers drive piles into the deep, fast-flowing Rhine and build a timber bridge several hundred metres long in ten days. The army spent eighteen days on the far bank burning the villages of the Sugambri, then returned to Gaul and dismantled the bridge behind it.']),
      w(-55, 1.1, 51.2,
        ['肯特（不列颠东南部）', '两度渡海远征不列颠', '前55年夏末，凯撒带两个军团渡过海峡，在今肯特郡海岸冒着不列颠人的阻击强行登陆，停留不到三周。次年他率五个军团和骑兵卷土重来，渡过泰晤士河，迫使部落首领卡西维劳努斯纳贡求和。两次远征没有留下驻军，却在罗马引起轰动。'],
        ['Kent (south-eastern Britain)', 'Twice crosses the Channel to Britain', 'Late in summer 55 BCE Caesar crossed the Channel with two legions, fought his way ashore in Kent and stayed less than three weeks. The next year he returned with five legions and cavalry, crossed the Thames and forced the war leader Cassivellaunus to offer hostages and tribute. No garrison was left, but the news caused a sensation in Rome.'],
        { via: [[1.62, 50.73]] }),
      w(-52, 4.5, 47.54,
        ['阿莱西亚（今法国阿利斯—圣雷讷）', '围攻阿莱西亚，平定高卢', '阿维尔尼人首领维钦托利联合高卢各部起义，在格尔戈维亚击退凯撒后退守山城阿莱西亚。凯撒环城修筑约十六公里的围城工事，外侧再筑一圈约二十一公里的防线抵御援军，同时击退内外夹攻。维钦托利出城投降，六年后在罗马被处死。'],
        ['Alesia (now Alise-Sainte-Reine, France)', 'Besieges Alesia and breaks the Gallic revolt', 'Vercingetorix of the Arverni united the Gallic peoples in revolt, repulsed Caesar at Gergovia, then withdrew to hilltop Alesia. Caesar ringed it with about 16 km of siege works and a second, outward-facing line of about 21 km against a relief army, and beat off attacks from both sides. Vercingetorix surrendered and was executed in Rome six years later.'],
        { via: [[1.62, 50.73]], wiki: { zh: '阿莱西亚之战', en: 'Battle of Alesia' } }),
      w(-49, 12.4, 44.1,
        ['卢比孔河（意大利北部，里米尼以北）', '率军渡过卢比孔河，内战爆发', '高卢总督任期将满，元老院在庞培支持下命令凯撒交出军队。前49年1月，他带着第十三军团越过山南高卢行省与意大利本土的界河卢比孔河，相传说了一句“骰子已经掷出”。庞培和多数元老仓皇撤离罗马，意大利各城望风而降。'],
        ['Rubicon (northern Italy, north of Rimini)', 'Crosses the Rubicon and begins the civil war', "With his command about to expire, the Senate, backed by Pompey, ordered Caesar to give up his army. In January 49 BCE he led the Thirteenth Legion across the Rubicon, the stream dividing his province from Italy proper, reportedly saying 'the die is cast'. Pompey and most senators abandoned Rome, and the towns of Italy opened their gates."],
        { wiki: { zh: '卢比孔河', en: 'Rubicon' } }),
      w(-49, 17.94, 40.63,
        ['布林迪西（古称布隆迪西乌姆，意大利东南部）', '追击庞培至布林迪西', '凯撒沿亚得里亚海岸南下，六十天内控制整个意大利，但庞培已率军从布林迪西渡海前往希腊。凯撒没有船只追击，便先回罗马，再西进西班牙，在伊莱尔达迫降庞培的军团。年底他回到布林迪西集结部队，准备渡海决战。'],
        ['Brundisium (now Brindisi, Italy)', 'Pursues Pompey to Brundisium', "Caesar swept down the Adriatic coast and held all Italy within sixty days, but Pompey got his army away from Brundisium to Greece. Having no ships, Caesar turned to Rome and then Spain, where he forced Pompey's legions to surrender at Ilerda. By the end of the year he was back at Brundisium, massing troops for the crossing."],
        { via: [[13.5, 43.3], [13.84, 42.12], [15.5, 41.45], [16.9, 40.95]] }),
      w(-48, 19.45, 41.32,
        ['底耳哈琴（今阿尔巴尼亚都拉斯）', '冬季渡海，围攻庞培失利', '凯撒冒着冬季风浪和敌方舰队的封锁，分两批把军队运过亚得里亚海，在底耳哈琴城外筑起长墙，试图把兵力占优的庞培围困在海边。七月庞培突破防线，凯撒损失上千人后撤往色萨利。他事后说，若对方有一位懂得取胜的统帅，战争那天就结束了。'],
        ['Dyrrhachium (now Durres, Albania)', 'Crosses in winter but fails to trap Pompey', 'Braving winter seas and the enemy fleet, Caesar ferried his army across the Adriatic and tried to pen Pompey, who had more men, against the coast at Dyrrhachium behind a line of fortifications. In July Pompey broke through; Caesar lost about a thousand men and retreated into Thessaly, saying the enemy could have won the war that day.'],
        { sea: true }),
      w(-48, 22.38, 39.29,
        ['法萨卢斯（希腊色萨利）', '击败庞培', '庞培在元老们催促下，以约两倍于对手的兵力在法萨卢斯平原决战。凯撒预料到敌军骑兵将包抄自己的右翼，暗设第四列步兵迎击，骑兵溃散后反过来包抄庞培左翼，大获全胜。庞培乔装逃往埃及，刚一上岸就被托勒密十三世的臣下杀害。'],
        ['Pharsalus (Thessaly, Greece)', 'Defeats Pompey', "Pressed by the senators in his camp, Pompey offered battle on the plain of Pharsalus with roughly twice Caesar's numbers. Foreseeing a cavalry attack on his right, Caesar had posted a hidden fourth line of infantry, which routed the horsemen and then turned Pompey's flank. Pompey fled in disguise to Egypt and was murdered as he stepped ashore."],
        { wiki: { zh: '法萨卢斯战役', en: 'Battle of Pharsalus' } }),
      w(-48, 29.92, 31.2,
        ['亚历山大里亚（今埃及亚历山大港）', '介入埃及王位之争，结识克利奥帕特拉', '凯撒追到亚历山大里亚，相传见到庞培的首级后落泪。他留下调解托勒密十三世与其姐克利奥帕特拉的王位之争，并与后者结为情人，结果被埃及军围困在王宫数月，大火还波及城中藏书。次年援军赶到，他击败埃及军，扶克利奥帕特拉重登王位。'],
        ['Alexandria (Egypt)', 'Intervenes in the Egyptian succession and meets Cleopatra', "Caesar followed Pompey to Alexandria and reportedly wept when shown his head. Staying to settle the quarrel between Ptolemy XIII and his sister Cleopatra, who became his lover, he was besieged in the palace for months; a fire he set in the harbour burned some of the city's books. Relieved next spring, he defeated the Egyptian army and restored Cleopatra."],
        { sea: true, via: [[24.0, 37.5], [27.0, 33.5]] }),
      w(-47, 35.9, 40.3,
        ['泽拉（今土耳其济莱）', '速胜本都国王：“我来，我见，我征服”', '本都国王法尔纳克二世趁罗马内战夺回其父的旧地。凯撒经叙利亚和奇里乞亚北上，抵达后第五天就在泽拉一战击溃本都军队，战斗仅数小时。他在给友人的信中只写了三个词：“我来，我见，我征服”（Veni, vidi, vici）。'],
        ['Zela (now Zile, Turkey)', 'Beats Pontus: "I came, I saw, I conquered"', 'Pharnaces II of Pontus had used the civil war to reclaim the lands of his father Mithridates VI. Leaving Egypt, Caesar marched north through Syria and Cilicia and destroyed the Pontic army at Zela within five days of arriving, in a battle that lasted a few hours. He summed it up to a friend in three words: Veni, vidi, vici.'],
        { via: [[32.55, 30.95], [33.8, 31.05], [34.45, 31.5], [35.2, 32.6], [36.0, 34.0], [36.16, 36.2], [34.9, 36.92], [35.49, 38.72]] }),
      w(-46, 11.06, 35.62,
        ['塔普苏斯（今突尼斯东海岸）', '击败庞培余部', '庞培派残部在阿非利加行省重新集结，由梅特卢斯·西庇阿统率，并得到努米底亚国王尤巴一世支持。凯撒在塔普苏斯城外击溃敌军，士兵不听号令大肆杀戮。小加图在乌提卡自杀，不愿接受凯撒的宽恕；努米底亚东部被并为罗马行省。'],
        ['Thapsus (east coast of Tunisia)', 'Defeats the remaining Pompeian forces', "Pompey's surviving partisans had regrouped in the province of Africa under Metellus Scipio, supported by King Juba I of Numidia. Caesar shattered their army outside Thapsus, where his soldiers got out of hand and gave no quarter. Cato the Younger killed himself at Utica rather than accept Caesar's pardon, and eastern Numidia became a Roman province."],
        { sea: true, via: [[29.0, 36.5], [18.0, 35.0]] }),
      w(-45, -4.95, 37.46,
        ['蒙达（今西班牙南部，战场位置有争议）', '结束内战', '庞培的两个儿子在西班牙聚集起十三个军团。凯撒从罗马出发，二十七天赶到前线，于前45年3月在蒙达与敌军血战。战况一度危急，他亲自冲到阵前才稳住军心，事后说以往是为胜利而战，这次是为性命而战。此战之后，内战结束。'],
        ['Munda (southern Spain; site of the battlefield disputed)', 'Ends the civil war', "Pompey's sons had raised thirteen legions in Spain. Caesar reached the front from Rome in twenty-seven days and fought them at Munda in March 45 BCE. It hung in the balance until he ran forward to rally his line; he said he had often fought for victory, but this time for his life. The civil war was over."],
        { sea: true, via: [[5.0, 37.5], [-2.0, 36.6]] }),
      w(-45, 12.4823, 41.8933,
        ['罗马', '独揽大权，推行儒略历', '凯撒回到罗马举行凯旋式，先后出任十年独裁官和终身独裁官。他采纳天文学家索西琴尼的建议，改行一年365天、四年一闰的太阳历，自前45年1月1日起施行；同时扩充元老院、安置老兵、向行省居民授予公民权，并筹划远征帕提亚。'],
        ['Rome', 'Holds supreme power and introduces the Julian calendar', 'In Rome Caesar celebrated a triumph and was named dictator for ten years, then for life. Advised by the astronomer Sosigenes he replaced the Roman calendar with a solar year of 365 days and a leap day every fourth year, in force from 1 January 45 BCE. He enlarged the Senate, settled veterans, extended citizenship and planned a Parthian war.'],
        { via: [[-3.8, 37.9], [-0.45, 39.5], [0.5, 40.85], [1.9, 41.75], [2.9, 42.45], [3.0, 43.2], [4.36, 43.84], [7.3, 43.72], [8.93, 44.41], [10.4, 43.72]], wiki: { zh: '儒略历', en: 'Julian calendar' } }),
      w(-44, 12.4823, 41.8933,
        ['罗马（庞培剧场）', '3月15日遇刺身亡', '出征帕提亚前三天，凯撒前往庞培剧场附设的会堂出席元老院会议。以布鲁图斯和卡西乌斯为首的数十名元老围上来拔出匕首，他身中二十三刀，倒在庞培雕像脚下。刺杀者自称恢复了共和，罗马却陷入新一轮内战，最终胜出的是他的养子屋大维。'],
        ['Rome (Theatre of Pompey)', 'Assassinated on the Ides of March', "Three days before leaving for the Parthian war, Caesar attended the Senate in the hall attached to the Theatre of Pompey. A group of senators led by Brutus and Cassius closed round him with daggers; he fell with twenty-three wounds at the foot of Pompey's statue. Instead of restoring the Republic, the murder opened another round of civil war."],
        { event: 'assassination-of-caesar' }),
    ],
    wiki: { zh: '尤利乌斯·凯撒', en: 'Julius Caesar' },
  },
  {
    id: 'cleopatra',
    name: { zh: '克利奥帕特拉七世', en: 'Cleopatra' },
    birth: -69, death: -30,
    title: { zh: '埃及托勒密王朝末代女王', en: 'Last queen of Ptolemaic Egypt' },
    region: 'africa', lineage: 'egypt', sprite: 'ship',
    summary: {
      zh: '埃及托勒密王朝最后一位实际掌权的君主，通称“埃及艳后”。她是马其顿希腊人后裔，十八岁即位，据普鲁塔克记载通晓多种语言，是王朝中第一位学会埃及语的统治者。在罗马内战的年代，她先后与凯撒和安东尼结盟并生育子女，借罗马之力保住王位、一度恢复了王朝在东地中海的旧疆。前31年亚克兴海战失败后，屋大维攻入埃及，她于次年自尽，埃及成为罗马行省，延续近三百年的托勒密王朝至此结束。',
      en: "The last active ruler of the Ptolemaic kingdom of Egypt. Of Macedonian Greek descent, she came to the throne at eighteen, and Plutarch credits her with speaking many languages, the first of her dynasty to learn Egyptian. In the age of Rome's civil wars she allied herself with Julius Caesar and then Mark Antony, bearing children to both, and used Roman power to keep her throne and briefly restore her dynasty's old empire in the eastern Mediterranean. After the defeat at Actium in 31 BCE, Octavian invaded Egypt and she took her own life; Egypt became a Roman province, and the Ptolemaic dynasty came to an end after nearly three centuries.",
    },
    route: [
      w(-69, 29.92, 31.2,
        ['亚历山大里亚（今埃及亚历山大港）', '生于托勒密王朝的都城', '克利奥帕特拉是国王托勒密十二世的女儿，母亲身份不详。她在王宫区长大，那里有著名的缪斯宫和图书馆。此时的埃及名义上独立，实则仰罗马鼻息：父亲曾被亚历山大里亚人赶下台，前55年靠重金贿买罗马将领、借罗马军队才得以复位。'],
        ['Alexandria (Egypt)', 'Born in the Ptolemaic capital', "Cleopatra was a daughter of King Ptolemy XII; her mother is uncertain. She grew up in the palace quarter beside the Museum and its famous library. Egypt was independent in name but lived in Rome's shadow: her father was driven out by the Alexandrians and regained his throne in 55 BCE only with a Roman army hired from a governor."],
        { wiki: { zh: '亚历山大图书馆', en: 'Library of Alexandria' } }),
      w(-51, 32.53, 25.62,
        ['赫尔蒙提斯（今埃及卢克索以南的艾尔曼特）', '十八岁即位，赴上埃及主持圣牛仪式', '托勒密十二世去世，遗嘱指定十八岁的克利奥帕特拉与十岁的弟弟托勒密十三世共同执政。据当地的布希斯圣牛石碑记载，即位当年春天，“女王、两地的女主人”亲自乘船把新选的圣牛护送到赫尔蒙提斯的神庙，以法老身份参与埃及的传统仪式。'],
        ['Hermonthis (now Armant, south of Luxor, Egypt)', 'Queen at eighteen; installs a sacred bull in Upper Egypt', "Ptolemy XII's will named the eighteen-year-old Cleopatra and her ten-year-old brother Ptolemy XIII joint rulers. A stele of the Buchis bulls records that in the spring of her first year 'the Queen, the Lady of the Two Lands' escorted the newly chosen sacred bull by boat to its temple at Hermonthis, taking part as pharaoh in traditional Egyptian rites."],
        { via: [[31.25, 29.9], [30.75, 28.1], [31.18, 27.18], [31.7, 26.56], [32.7, 26.15]] }),
      w(-48, 32.57, 31.04,
        ['贝鲁西亚（尼罗河三角洲东端，今埃及法拉马丘）', '被逐后募兵叙利亚，回师对峙', '托勒密十三世身边的宦官波提努斯等权臣把克利奥帕特拉赶出亚历山大里亚，她逃往叙利亚招募雇佣军，回到埃及东部边境的贝鲁西亚附近，与弟弟的军队对峙。就在这时，法萨卢斯战败的庞培逃到此地，被托勒密十三世的臣下诱杀。'],
        ['Pelusium (eastern edge of the Nile delta, now Tell el-Farama, Egypt)', 'Driven out, she returns with an army from Syria', "Ousted from Alexandria by her brother's ministers, led by the eunuch Pothinus, Cleopatra fled to Syria, raised a force of mercenaries and marched back to the eastern frontier near Pelusium, where her brother's army barred the way. It was here that Pompey, fleeing from his defeat at Pharsalus, came ashore and was murdered on the orders of Ptolemy XIII's advisers."],
        { via: [[32.7, 26.15], [31.7, 26.56], [31.18, 27.18], [30.75, 28.1], [31.25, 29.9], [29.92, 31.2], [31.3, 30.5], [33.4, 30.6], [34.6, 31.6], [33.9, 31.05], [33.1, 30.98]] }),
      w(-48, 29.92, 31.2,
        ['亚历山大里亚', '潜入王宫会见凯撒', '凯撒抵达后召姐弟二人前来听候裁决。据普鲁塔克记载，克利奥帕特拉让亲信把自己裹在铺盖卷里，乘小船趁夜潜入王宫，二十一岁的女王由此赢得了凯撒的支持。托勒密十三世在随后的战事中溺死于尼罗河，她与幼弟托勒密十四世共治，实权在握。'],
        ['Alexandria', 'Slips into the palace to meet Caesar', 'Caesar, newly arrived, summoned brother and sister to his arbitration. Plutarch tells how Cleopatra had a servant carry her past the guards by night rolled in a bedding sack, and the twenty-one-year-old queen won Caesar over. Ptolemy XIII drowned in the Nile in the war that followed, and she ruled with her younger brother Ptolemy XIV as a figurehead.'],
        { sea: true, via: [[32.0, 31.65], [31.0, 31.8], [30.3, 31.6]] }),
      w(-47, 32.67, 26.14,
        ['尼罗河上游（今埃及丹德拉一带，位置为示意）', '与凯撒泛舟尼罗河', '战事平息后，据阿庇安和苏埃托尼乌斯记载，克利奥帕特拉陪凯撒乘船溯尼罗河而上巡游，阿庇安说有四百艘船随行，两人究竟走了多远已不可考。在上游的丹德拉，哈索尔神庙后墙上至今保存着她和儿子凯撒里昂向诸神献祭的巨幅浮雕。'],
        ['Upper Nile (around Dendera, Egypt; location indicative)', 'Cruises the Nile with Caesar', 'After the fighting, Appian and Suetonius report, Cleopatra took Caesar on a journey up the Nile; Appian speaks of an escort of 400 ships. How far they went is unknown. At Dendera in Upper Egypt, a colossal relief on the rear wall of the temple of Hathor still shows her and her son Caesarion making offerings to the gods.'],
        { via: [[31.25, 29.9], [30.75, 28.1], [31.18, 27.18], [31.7, 26.56]] }),
      w(-47, 29.92, 31.2,
        ['亚历山大里亚', '生下凯撒之子凯撒里昂', '凯撒于前47年离开埃及，留下三个军团驻守。同年夏天克利奥帕特拉生下一子，取名托勒密·凯撒，亚历山大里亚人叫他“凯撒里昂”（小凯撒）。凯撒从未正式承认这个儿子，但也没有阻止她用这个名字；孩子的父亲是谁，在罗马一直有人质疑。'],
        ['Alexandria', 'Gives birth to Caesarion', "Caesar left Egypt in 47 BCE, leaving three legions to protect the queen. That summer Cleopatra bore a son, Ptolemy Caesar, whom the Alexandrians nicknamed Caesarion, 'little Caesar'. Caesar never formally acknowledged the boy, though he let her use the name, and his paternity was questioned at Rome."],
        { via: [[31.7, 26.56], [31.18, 27.18], [30.75, 28.1], [31.25, 29.9]], wiki: { zh: '托勒密十五世', en: 'Caesarion' } }),
      w(-46, 12.46, 41.88,
        ['罗马（台伯河西岸的凯撒庄园）', '携子访问罗马', '克利奥帕特拉带着幼子和共治的弟弟来到罗马，住在凯撒位于台伯河对岸的庄园里，被正式承认为“罗马人民的朋友和同盟”。凯撒在新建的维纳斯神庙中安放了她的镀金雕像，引起不少罗马人的反感。凯撒遇刺后，她在前44年春返回埃及。'],
        ["Rome (Caesar's villa across the Tiber)", 'Visits Rome with her son', "Cleopatra came to Rome with her child and her brother-king and lodged in Caesar's villa beyond the Tiber; she was recognised as a friend and ally of the Roman people. Caesar placed a gilded statue of her in his new temple of Venus Genetrix, to the disgust of many Romans. After his assassination she sailed home in spring 44 BCE."],
        { sea: true, via: [[27.0, 33.0], [23.5, 34.5], [20.0, 36.2], [16.3, 37.6], [15.62, 37.95], [15.6, 38.2], [15.68, 38.3], [15.4, 38.6], [13.9, 40.3], [12.2, 41.65]] }),
      w(-44, 29.92, 31.2,
        ['亚历山大里亚', '返回埃及，立幼子为共治者', '回国后不久，托勒密十四世去世，古代史家怀疑是被她毒死的。克利奥帕特拉把三岁的凯撒里昂立为共治者，称托勒密十五世。此后两年尼罗河水位过低，埃及发生饥荒和瘟疫，她一面开仓赈济，一面在刺杀凯撒者与后三头之间观望周旋。'],
        ['Alexandria', 'Returns to Egypt and makes her son co-ruler', "Soon after her return Ptolemy XIV died; ancient writers suspected that she had him poisoned. Cleopatra made the three-year-old Caesarion her co-ruler as Ptolemy XV. For two years the Nile flood failed, bringing famine and plague, while she distributed grain and manoeuvred between Caesar's assassins and the triumvirs who were hunting them."],
        { sea: true, via: [[12.2, 41.65], [13.9, 40.3], [15.4, 38.6], [15.68, 38.3], [15.6, 38.2], [15.62, 37.95], [16.3, 37.6], [20.0, 36.2], [23.5, 34.5], [27.0, 33.0]] }),
      w(-41, 34.9, 36.92,
        ['塔尔苏斯（奇里乞亚，今土耳其南部）', '盛装溯河会见安东尼', '腓立比战后，掌管东方的安东尼召她到塔尔苏斯，要她解释资助刺杀者卡西乌斯的传闻。据普鲁塔克描写，她乘坐船尾镀金、张着紫帆、银桨随笛声划动的画舫溯基德诺斯河而来，自己扮作爱神阿佛洛狄忒。安东尼为之倾倒，随她去了亚历山大里亚。'],
        ['Tarsus (Cilicia, southern Turkey)', 'Sails up the Cydnus to meet Mark Antony', 'After Philippi, Antony, now master of the East, summoned Cleopatra to Tarsus to answer charges that she had aided Cassius. Plutarch describes her arrival up the river Cydnus in a barge with a gilded stern, purple sails and silver oars beating time to flutes, herself dressed as Aphrodite. Antony was captivated and followed her to Alexandria.'],
        { sea: true, via: [[31.3, 33.2], [32.0, 35.0], [33.2, 35.85], [34.6, 36.55]], wiki: { zh: '塔尔苏斯', en: 'Tarsus, Mersin' } }),
      w(-41, 29.92, 31.2,
        ['亚历山大里亚', '与安东尼共度冬天', '安东尼在亚历山大里亚度过前41至前40年的冬天，两人组织了名为“无与伦比的生活者”的宴饮会社。按他的命令，与她争位的妹妹阿尔西诺伊四世在以弗所被处死。次年春安东尼离去，她生下一对双胞胎，此后三年多两人未再见面。'],
        ['Alexandria', 'Spends the winter with Antony', 'Antony passed the winter of 41-40 BCE in Alexandria, where the two founded a dining club called the Inimitable Livers. On his orders her sister and rival Arsinoe IV was put to death at Ephesus. After he left in spring 40 BCE Cleopatra bore twins, Alexander Helios and Cleopatra Selene; the couple did not meet again for over three years.'],
        { sea: true, via: [[34.6, 36.55], [33.2, 35.85], [32.0, 35.0], [31.3, 33.2]] }),
      w(-37, 36.16, 36.2,
        ['安条克（今土耳其安塔基亚）', '与安东尼重聚，获赠东方领地', '安东尼为筹备远征帕提亚回到东方，把克利奥帕特拉请到安条克。他把塞浦路斯、奇里乞亚沿海、腓尼基和柯里叙利亚的大片土地划归埃及，这些地区盛产造船的木材。她从这时起使用新的双重纪年；次年生下第三个孩子托勒密·费拉德尔福斯。'],
        ['Antioch (now Antakya, Turkey)', 'Reunited with Antony, who grants her eastern territories', 'Returning east to prepare his Parthian war, Antony sent for Cleopatra at Antioch. He assigned to Egypt Cyprus, parts of the Cilician coast, Phoenicia and Coele-Syria, lands rich in the timber needed for ships. She marked the event by adopting a new double system of regnal dates, and the following year bore her third child by him, Ptolemy Philadelphus.'],
        { sea: true, via: [[30.2, 31.7], [32.5, 32.5], [34.6, 34.2], [35.55, 35.7], [35.88, 36.08]], wiki: { zh: '安条克', en: 'Antioch' } }),
      w(-34, 29.92, 31.2,
        ['亚历山大里亚', '“亚历山大里亚的赠礼”', '安东尼征服亚美尼亚后在此举行凯旋游行。在体育馆的典礼上，两人高坐金椅，克利奥帕特拉身着伊西斯女神的装束，被尊为“众王之女王”，凯撒里昂被宣布为凯撒之子、“众王之王”，三个幼子各获封东方的王国。屋大维借此在罗马大做文章。'],
        ['Alexandria', 'The Donations of Alexandria', "After conquering Armenia, Antony staged a triumphal procession in Alexandria. At a ceremony in the Gymnasium the pair sat on golden thrones, Cleopatra robed as Isis and proclaimed Queen of Kings, Caesarion declared Caesar's true son and King of Kings, and their three young children assigned kingdoms in the East. In Rome, Octavian made the most of the scandal."],
        { sea: true, via: [[35.88, 36.08], [35.55, 35.7], [34.6, 34.2], [32.5, 32.5], [30.2, 31.7]] }),
      w(-33, 27.34, 37.94,
        ['以弗所（今土耳其塞尔丘克）', '随安东尼集结舰队', '与屋大维决裂在即，安东尼在以弗所集结了约八百艘战船和运输船，其中两百艘由克利奥帕特拉提供，她还带来巨额军费和粮食。安东尼的一些罗马部将要求把她送回埃及，她坚持留在军中。前32年两人经萨摩斯岛前往雅典。'],
        ['Ephesus (now Selcuk, Turkey)', 'Joins Antony as he gathers his fleet', "With the break with Octavian approaching, Antony assembled some 800 warships and transports at Ephesus; Cleopatra supplied 200 of them, with a huge war chest and grain. Some of Antony's Roman officers urged him to send her back to Egypt, but she insisted on staying with the army. In 32 BCE the couple moved on via Samos to Athens."],
        { sea: true, via: [[28.3, 33.5], [27.5, 35.6], [26.95, 36.3], [26.7, 36.9], [26.48, 37.6], [26.8, 37.93]] }),
      w(-32, 23.7275, 37.9838,
        ['雅典', '安东尼休妻，罗马对她宣战', '在雅典，安东尼正式与屋大维的姐姐屋大维娅离婚。屋大维在罗马公布了据称是安东尼的遗嘱，其中要求死后葬在亚历山大里亚，舆论哗然。罗马元老院剥夺安东尼的权力，却只对克利奥帕特拉一人宣战，把内战说成一场对外战争。'],
        ['Athens', 'Antony divorces Octavia; Rome declares war on her', "At Athens Antony formally divorced Octavia, the sister of Octavian. Octavian then published what he said was Antony's will, with its request to be buried in Alexandria, and Roman opinion turned sharply. The Senate stripped Antony of his powers but declared war on Cleopatra alone, presenting the civil war as a foreign one."],
        { sea: true, via: [[26.8, 37.93], [26.3, 37.85], [25.2, 38.1], [24.7, 38.06], [24.6, 37.93], [24.22, 37.8], [24.03, 37.55], [23.78, 37.72]] }),
      w(-31, 20.73, 38.95,
        ['亚克兴（希腊西海岸，安布拉基亚湾口）', '亚克兴海战，率船队突围', '安东尼的陆海军被阿格里帕的舰队封锁在安布拉基亚湾内，补给断绝、疫病流行。9月2日舰队出战，克利奥帕特拉带着载有金库的六十艘船趁午后起风扬帆冲出重围，安东尼随即弃军追随。留下的舰队和陆军相继投降，胜负就此决定。'],
        ['Actium (mouth of the Ambracian Gulf, western Greece)', 'Breaks out with her squadron at the Battle of Actium', "Agrippa's fleet had bottled up Antony's army and navy in the Ambracian Gulf, where hunger and disease thinned them. When the fleet came out on 2 September, Cleopatra's sixty ships, carrying the treasury, hoisted sail on the afternoon breeze and broke through to the open sea; Antony abandoned his forces to follow her. The remaining fleet and army soon surrendered."],
        { sea: true, via: [[23.78, 37.72], [23.8, 37.35], [23.4, 36.3], [22.95, 36.0], [22.35, 36.2], [21.5, 36.55], [21.1, 37.3], [20.35, 37.7], [20.15, 38.25], [20.4, 38.75], [20.65, 38.97]], event: 'battle-of-actium' }),
      w(-30, 29.92, 31.2,
        ['亚历山大里亚', '屋大维入城，自尽身亡', '前30年8月1日屋大维攻入城中，安东尼伏剑自杀，死在克利奥帕特拉怀中。她得知自己将被带往罗马凯旋式示众，约十天后自尽，年三十九岁，按遗愿与安东尼合葬。古代多传说她让毒蛇咬死自己，真实死因已不可考。凯撒里昂随后被处死。'],
        ['Alexandria', 'Takes her own life after Octavian captures the city', "Octavian entered Alexandria on 1 August 30 BCE; Antony fell on his sword and died in Cleopatra's arms. Learning that she was to be paraded in Octavian's triumph, she killed herself about ten days later, aged thirty-nine, and was buried beside Antony as she had asked. Tradition says she used a snake's bite, but how she died is unknown."],
        { sea: true, via: [[20.65, 38.97], [20.4, 38.75], [20.15, 38.25], [20.35, 37.7], [21.1, 37.0], [21.6, 36.4], [23.5, 34.6], [27.0, 33.0]] }),
    ],
    wiki: { zh: '克利奥帕特拉七世', en: 'Cleopatra' },
  },
  {
    id: 'augustus',
    name: { zh: '奥古斯都', en: 'Augustus' },
    birth: -63, death: 14,
    title: { zh: '罗马帝国首位皇帝', en: 'First Roman emperor' },
    region: 'europe', lineage: 'rome', sprite: 'crown',
    summary: {
      zh: '罗马帝国第一位皇帝，原名盖乌斯·屋大维，凯撒的甥孙和养子。凯撒遇刺后，十八岁的他以继承人身份崛起，先与安东尼、雷必达结成“后三头同盟”击败刺杀者，再于亚克兴击败安东尼，结束了长达百年的内战。前27年获“奥古斯都”尊号，以“元首”名义行帝制之实，在位四十余年，整顿行省、军队与财政，开启了约两百年的“罗马和平”。',
      en: "The first Roman emperor, born Gaius Octavius, great-nephew and adopted son of Julius Caesar. After Caesar's murder he emerged at eighteen as his heir, joined Mark Antony and Lepidus in the Second Triumvirate to destroy the assassins, and then defeated Antony at Actium, ending a century of civil wars. In 27 BCE the Senate named him Augustus. Ruling as princeps, 'first citizen', behind republican forms, he reorganised the provinces, the army and the finances over a reign of more than forty years and inaugurated some two centuries of relative peace, the Pax Romana.",
    },
    route: [
      w(-63, 12.4823, 41.8933,
        ['罗马', '生于罗马', '屋大维于9月23日出生在帕拉蒂尼山。父亲出身罗马东南小城韦莱特里的骑士家庭，是家族中第一个进入元老院的人，在他四岁时去世；母亲阿提娅是凯撒的外甥女。没有儿子的凯撒很看重这个少年，前45年在遗嘱中把他立为养子和主要继承人。'],
        ['Rome', 'Born in Rome', "Octavius was born on the Palatine on 23 September. His father, from an equestrian family of Velitrae, was the first of his line in the Senate and died when the boy was four; his mother Atia was Caesar's niece. The childless Caesar favoured him and in 45 BCE named him in his will as adopted son and heir."]),
      w(-44, 19.56, 40.72,
        ['阿波罗尼亚（今阿尔巴尼亚费里附近）', '闻凯撒遇刺，以养子身份返回罗马', '十八岁的屋大维正在亚得里亚海东岸的阿波罗尼亚求学，并随驻军演练，准备参加凯撒的帕提亚远征，同伴中有日后的名将阿格里帕。凯撒遇刺的消息传来，家人来信劝他谨慎行事，军官们则愿意拥他起兵；他决定先渡海回意大利察看形势。'],
        ['Apollonia (near Fier, Albania)', "Learns of Caesar's murder and returns as his heir", "The eighteen-year-old Octavius was studying and training with the army at Apollonia, across the Adriatic, ready to join Caesar's Parthian campaign; his friend Agrippa was with him. When news of the murder came, his family urged caution while officers offered him the army's support. He chose to cross quietly to Italy and see how matters stood."],
        { via: [[14.6, 41.1], [17.94, 40.63]] }),
      w(-44, 17.94, 40.63,
        ['布林迪西（古称布隆迪西乌姆，意大利东南部）', '渡海回国，以“凯撒”之名争取老兵', '屋大维在布林迪西以南登岸，得知遗嘱内容后进城，受到凯撒老兵的欢迎，从此自称“凯撒”。到罗马后，安东尼拒不交出凯撒的遗产，他便变卖家产向市民发放凯撒许诺的赠款；七月他为凯撒举办竞技会时天空出现彗星，被说成凯撒成神的征兆。'],
        ['Brundisium (now Brindisi, Italy)', "Lands in Italy and takes Caesar's name", "Octavius landed south of Brundisium, learned of the will and was welcomed in the port by Caesar's veterans; he now called himself Caesar. In Rome Antony withheld Caesar's funds, so he sold property to pay Caesar's bequests to the people. A comet seen during his games for Caesar in July was hailed as the dictator's soul among the gods."],
        { sea: true }),
      w(-43, 10.93, 44.65,
        ['穆蒂纳（今意大利摩德纳）', '助元老院击败安东尼，夺得执政官', '屋大维自费招募凯撒旧部，在西塞罗支持下获元老院授权，与两位执政官北上解救被安东尼围困在穆蒂纳的德奇姆斯·布鲁图斯。安东尼战败西撤，两位执政官却双双阵亡。元老院随即冷落屋大维，他率八个军团进军罗马，年仅十九岁便当上执政官。'],
        ['Mutina (now Modena, Italy)', 'Defeats Antony for the Senate, then seizes the consulship', "Octavian raised an army of Caesar's veterans at his own expense and, with Cicero's backing, was sent by the Senate with the two consuls to relieve Decimus Brutus, besieged by Antony at Mutina. Antony was beaten and withdrew west, but both consuls died. Slighted by the Senate, Octavian marched on Rome with eight legions and was elected consul at nineteen."],
        { via: [[14.25, 41.08], [12.48, 41.89], [12.57, 44.06]] }),
      w(-43, 12.4823, 41.8933,
        ['罗马', '与安东尼、雷必达结成“后三头同盟”', '屋大维转而与安东尼、雷必达和解，三人在博洛尼亚附近的河心小岛上会谈两天，约定共掌国政五年、瓜分西部行省。同盟经公民大会立法确认后，三人回到罗马公布“公敌名单”，约三百名元老和两千名骑士被列入，西塞罗也在其中遇害。'],
        ['Rome', 'Forms the Second Triumvirate with Antony and Lepidus', 'Octavian now came to terms with Antony and Lepidus. Meeting for two days on a river island near Bononia (Bologna), the three agreed to share supreme power for five years and divide the western provinces. With the pact ratified by law, they entered Rome and posted proscription lists naming some 300 senators and 2,000 equestrians; Cicero was among those killed.'],
        { via: [[11.34, 44.49]] }),
      w(-42, 24.29, 41.01,
        ['腓立比（今希腊东马其顿）', '击败刺杀凯撒的布鲁图斯与卡西乌斯', '三头的军队在腓立比城西的平原上与共和派决战，两次会战相隔约三周。屋大维抱病在身，第一战中营地被布鲁图斯攻破，全靠安东尼击溃卡西乌斯；卡西乌斯和布鲁图斯先后自杀。战后安东尼留在东方，屋大维回意大利为数万名老兵分配土地。'],
        ['Philippi (eastern Macedonia, Greece)', "Defeats Caesar's assassins Brutus and Cassius", 'The triumvirs met the republican army west of Philippi in two battles about three weeks apart. Octavian was ill, and in the first his camp was overrun by Brutus while Antony broke Cassius; Cassius and then Brutus killed themselves. Antony stayed to organise the East, and Octavian went back to Italy to find land for tens of thousands of veterans.'],
        { via: [[17.94, 40.63], [19.45, 41.32], [22.95, 40.64]], wiki: { zh: '腓立比战役', en: 'Battle of Philippi' } }),
      w(-40, 12.39, 43.11,
        ['佩鲁西亚（今意大利佩鲁贾）', '佩鲁西亚之战，平定意大利内乱', '为安置老兵而没收土地激起意大利各地的反抗，安东尼的弟弟卢基乌斯和妻子富尔维娅乘机起兵。屋大维把卢基乌斯围困在佩鲁西亚，城中断粮后于前40年初投降，城市遭洗劫焚毁。屋大维赦免了卢基乌斯，却处死了城中的议员。'],
        ['Perusia (now Perugia, Italy)', 'Wins the Perusine War in Italy', "The confiscation of land for the veterans stirred revolt across Italy, and Antony's brother Lucius and wife Fulvia took up arms against Octavian. He shut Lucius up in Perusia until famine forced its surrender early in 40 BCE; the city was sacked and burned. Octavian spared Lucius but had the town councillors executed."],
        { via: [[22.95, 40.64], [19.45, 41.32], [17.94, 40.63], [12.48, 41.89]] }),
      w(-40, 17.94, 40.63,
        ['布林迪西', '《布林迪西和约》，与安东尼划分东西', '安东尼率舰队返回意大利，双方的老兵却不愿自相残杀，逼着两位统帅讲和。按照和约，安东尼掌管东方，屋大维掌管西方，雷必达只保有阿非利加；安东尼迎娶屋大维的姐姐屋大维娅。维吉尔的《牧歌》第四首作于此时，期盼一个新的黄金时代。'],
        ['Brundisium', 'Divides the Roman world with Antony at Brundisium', "Antony sailed back to Italy, but the veterans on both sides refused to fight each other and pushed their generals into a settlement. Antony took the East, Octavian the West, and Lepidus was left with Africa; Antony married Octavian's sister Octavia. Virgil's Fourth Eclogue, written about this time, looks forward to a new golden age."],
        { via: [[12.48, 41.89], [14.6, 41.1]] }),
      w(-36, 15.38, 38.23,
        ['瑙洛库斯（西西里岛东北海岸）', '击败塞克斯图斯·庞培，独掌西方', '庞培之子塞克斯图斯占据西西里，用舰队封锁意大利的粮食运输。屋大维本人屡次在海上失利，最终靠阿格里帕新建的舰队在瑙洛库斯海战中将其击溃。雷必达企图趁机夺取西西里，却被部下抛弃，从此退出政坛，屋大维成为西部唯一的主宰。'],
        ['Naulochus (north-east coast of Sicily)', 'Defeats Sextus Pompey and becomes master of the West', "Sextus Pompey, son of Pompey the Great, held Sicily and used his fleet to cut off Italy's grain supply. Octavian was beaten more than once at sea, but Agrippa's new fleet destroyed Sextus's navy off Naulochus. When Lepidus then tried to claim Sicily his troops deserted him and he was forced to retire, leaving Octavian sole ruler of the West."],
        { via: [[16.6, 40.3], [16.25, 39.3], [15.75, 38.2]] }),
      w(-31, 20.73, 38.95,
        ['亚克兴（希腊西海岸，安布拉基亚湾口）', '海战大败安东尼与克利奥帕特拉', '屋大维让意大利和西部行省宣誓效忠，以讨伐埃及女王的名义出兵。阿格里帕攻占沿海据点、切断补给，把敌军困在安布拉基亚湾。9月2日决战，克利奥帕特拉和安东尼突围南逃，余部投降。屋大维后来在营地旧址建起“胜利城”尼科波利斯。'],
        ['Actium (mouth of the Ambracian Gulf, western Greece)', 'Defeats Antony and Cleopatra at sea', "Having received an oath of loyalty from Italy and the western provinces, Octavian declared war on the queen of Egypt. Agrippa seized coastal bases, cut the enemy's supplies and trapped them in the Ambracian Gulf. On 2 September Cleopatra and Antony broke out and fled south and the rest surrendered. Octavian founded Nicopolis, 'Victory City', where he had camped."],
        { sea: true, via: [[15.55, 38.33], [15.68, 38.3], [15.6, 38.2], [15.62, 37.95], [16.2, 37.75], [18.5, 38.4], [20.4, 38.75], [20.65, 38.97]], event: 'battle-of-actium' }),
      w(-30, 29.92, 31.2,
        ['亚历山大里亚（今埃及亚历山大港）', '攻入埃及，托勒密王朝灭亡', '屋大维在萨摩斯岛过冬后，经叙利亚从东面进入埃及，前30年8月1日占领亚历山大里亚。安东尼和克利奥帕特拉先后自杀，凯撒里昂被处死。埃及成为由屋大维直接委派骑士总督治理的行省，托勒密王室的巨额财富让他得以清偿债务、安置老兵。'],
        ['Alexandria (Egypt)', 'Invades Egypt; the Ptolemaic dynasty ends', 'After wintering on Samos, Octavian advanced on Egypt through Syria and took Alexandria on 1 August 30 BCE. Antony and Cleopatra killed themselves and Caesarion was put to death. Egypt became a province governed by an equestrian prefect answerable to Octavian alone, and the Ptolemaic treasure allowed him to pay his debts and settle his veterans.'],
        { sea: true, via: [[22.0, 36.0], [27.0, 33.0]] }),
      w(-27, 12.4823, 41.8933,
        ['罗马', '获“奥古斯都”尊号，罗马帝国开始', '屋大维于前29年回到罗马，连续三天举行凯旋式，关闭雅努斯神庙大门以示天下太平。前27年1月，他在元老院宣布交还非常权力，把国家“交还元老院和人民”；元老院则请他继续统辖驻有重兵的行省，并授予“奥古斯都”（至尊者）的称号。'],
        ['Rome', 'Receives the name Augustus; the Roman Empire begins', "Octavian returned to Rome in 29 BCE, celebrated a triple triumph and closed the temple of Janus to mark peace. In January 27 BCE he announced he was handing the state back to the Senate and people; the senators asked him to keep the provinces that held most of the legions and voted him the name Augustus, 'the revered one'."],
        { sea: true, via: [[22.0, 35.0], [15.5, 37.6], [14.0, 40.5]], event: 'augustus-principate' }),
      w(-26, 1.25, 41.12,
        ['塔拉科（今西班牙塔拉戈纳）', '亲征西班牙北部的坎塔布里人', '奥古斯都经高卢来到西班牙，亲自指挥对半岛北部山区坎塔布里人和阿斯图里亚斯人的战争，这是他最后一次亲临前线。他不久病倒，在塔拉科休养近两年，并在此就任执政官、接见远方的使团。西班牙全境的征服，要到前19年才由阿格里帕完成。'],
        ['Tarraco (now Tarragona, Spain)', 'Campaigns against the Cantabri of northern Spain', 'Augustus travelled through Gaul to Spain and took command of the war against the Cantabri and Astures in the northern mountains, the last time he led an army in the field. He soon fell ill and spent nearly two years at Tarraco, where he entered two consulships and received distant embassies. Agrippa completed the conquest only in 19 BCE.'],
        { via: [[10.4, 43.72], [8.93, 44.41], [7.3, 43.72], [4.36, 43.84], [3.0, 43.2], [2.9, 42.45], [1.9, 41.75]], wiki: { zh: '塔拉戈纳', en: 'Tarragona' } }),
      w(-23, 12.4823, 41.8933,
        ['罗马', '大病之后重定元首权力', '奥古斯都一度病危，把印章戒指交给了阿格里帕。病愈后他辞去连任多年的执政官，改由元老院授予终身的保民官权力和高于各行省总督的统治权，这成为此后历代皇帝权力的法律基础。同年他属意的继承人、外甥兼女婿马凯路斯病逝。'],
        ['Rome', 'Recasts his powers after a near-fatal illness', "Augustus fell so ill that he handed his signet ring to Agrippa. Recovering, he gave up the consulship he had held every year and received from the Senate tribunician power for life and an authority superior to that of provincial governors, the legal basis of every later emperor's rule. His nephew and son-in-law Marcellus, his likely heir, died that year."],
        { via: [[1.9, 41.75], [2.9, 42.45], [3.0, 43.2], [4.36, 43.84], [7.3, 43.72], [8.93, 44.41], [10.4, 43.72]] }),
      w(-20, 36.16, 36.2,
        ['叙利亚行省（安条克，今土耳其安塔基亚）', '巡视东方，迎回被帕提亚夺走的鹰旗', '奥古斯都用三年巡视西西里、希腊、小亚细亚和叙利亚。在外交压力下，帕提亚国王交还了前53年克拉苏在卡莱丢失的军团鹰旗和战俘，由继子提比略前往接收。这一不战而得的成果被大加宣扬，“第一门的奥古斯都像”的胸甲上就刻着这一场面。'],
        ['Province of Syria (Antioch, now Antakya, Turkey)', 'Tours the East and recovers the standards lost to Parthia', 'Augustus spent three years touring Sicily, Greece, Asia Minor and Syria. Under diplomatic pressure the Parthian king Phraates IV gave back the legionary eagles and prisoners taken from Crassus at Carrhae in 53 BCE, which his stepson Tiberius went to receive. The bloodless success was celebrated widely; the scene is carved on the breastplate of the Augustus of Prima Porta.'],
        { sea: true, via: [[12.2, 41.65], [13.9, 40.3], [15.4, 38.6], [15.68, 38.3], [15.6, 38.2], [15.62, 37.95], [16.3, 37.6], [21.5, 36.2], [23.5, 34.55], [27.0, 34.3], [32.0, 34.2], [34.6, 34.25], [35.55, 35.7], [35.88, 36.08]] }),
      w(-17, 12.4823, 41.8933,
        ['罗马', '东巡归来，举行世纪庆典', '前19年奥古斯都自东方返回，同行的诗人维吉尔病逝途中，遗作《埃涅阿斯纪》由他下令发表。次年他推动立法鼓励婚育、惩治通奸，前17年主持世纪庆典，宣告新时代来临。前13年元老院决议修建的“和平祭坛”，复原后陈列在台伯河畔。'],
        ['Rome', 'Returns from the East and holds the Secular Games', 'Augustus returned from the East in 19 BCE; the poet Virgil died on the journey, and Augustus had his unfinished Aeneid published. Laws to encourage marriage and punish adultery followed, and in 17 BCE he presided over the Secular Games proclaiming a new age. The Altar of Augustan Peace, decreed in 13 BCE, stands rebuilt beside the Tiber.'],
        { sea: true, via: [[35.88, 36.08], [35.55, 35.7], [34.6, 34.25], [32.0, 34.2], [27.0, 34.3], [23.5, 34.55], [21.5, 36.2], [16.3, 37.6], [15.62, 37.95], [15.6, 38.2], [15.68, 38.3], [15.4, 38.6], [13.9, 40.3], [12.2, 41.65]], wiki: { zh: '和平祭坛', en: 'Ara Pacis' } }),
      w(14, 14.53, 40.93,
        ['诺拉（今意大利那不勒斯以东）', '病逝，被元老院尊为神', '晚年他接连失去指定的继承人，公元9年又有三个军团在条顿堡森林覆没，相传他常喊“瓦卢斯，还我军团！”公元14年8月19日，他在送继子提比略出征途中病逝于诺拉，终年七十五岁，被元老院尊为神。自撰的《功业录》刻在其陵墓前。'],
        ['Nola (east of Naples, Italy)', 'Dies and is deified by the Senate', "Augustus outlived one chosen heir after another, and in 9 CE three legions were lost in the Teutoburg Forest; he reportedly cried, 'Varus, give me back my legions!' On 19 August 14 CE, after seeing off his stepson Tiberius, he died at Nola aged seventy-five. The Senate declared him a god; his Res Gestae was inscribed before his mausoleum."],
        { wiki: { zh: '奥古斯都陵墓', en: 'Mausoleum of Augustus' } }),
    ],
    wiki: { zh: '奥古斯都', en: 'Augustus' },
  },
];
